comms.text:
@1 וִיהֵי חֳלַף דִי תְקַבְּלוּן יָת דִינַיָא הָאִלֵין וְתִטְרוּן וְתַעְבְּדוּן יָתְהוֹן וְיִטַר יְיָ אֱלָהָךְ לָךְ יָת קְיָמָא וְיָת חִסְדָא דִי קַיִים לַאֲבָהָתָךְ:
@2 וְיִרְחֲמִנָךְ וִיבָרֵכִנָךְ וְיַסְגִינָךְ וִיבָרֵךְ וַלְדָא דִמְעָךְ וְאִבָּא דְאַרְעָךְ עִבוּרָךְ וְחַמְרָךְ וּמִשְׁחָךְ בַּקְרֵי תוֹרָיךְ וְעֶדְרֵי עָנָךְ עַל אַרְעָא דִי קַיִים לַאֲבָהָתָךְ לְמִתַּן לָךְ:
@3 בְּרִיךְ תְּהֵי מִכָּל עַמְמַיָא לָא יְהֵי בָךְ עֲקַר וְעַקְרָא וּבִבְעִירָךְ:
@4 וְיֶעְדֵי יְיָ מִנָךְ כָּל מַרְעִין וְכָל מַכְתְּשֵׁי מִצְרַיִם בִּישַׁיָא דִי יְדַעַתְּ לָא יְשַׁוִּנוּן בָּךְ וְיִתְּנִנוּן בְּכָל סָנְאָךְ:
@5 וּתְגַמַר יָת כָּל עַמְמַיָא דִי יְיָ אֱלָהָךְ יָהֵב לָךְ לָא תְחוּס עֵינָךְ עֲלֵיהוֹן וְלָא תִפְלַח יָת טַּעֲוָתְהוֹן אֲרֵי לְתַקְלָא הוּא לָךְ:
@6 דִילְמָא תֵימַר בְּלִבָּךְ סַגִיאִין עַמְמַיָא הָאִלֵין מִנִי אֶכְדֵין אִכּוּל לְתָרָכוּתְהוֹן:
@7 לָא תִדְחַל מִנְהוֹן מִדְכַּר תִּדְכַּר יָת דִי עֲבַד יְיָ אֱלָהָךְ לְפַרְעֹה וּלְכָל מִצְרָיִם:
@8 נִסִין רַבְרְבִין דִי חֲזָאָה עֵינָךְ וְאָתַיָא וּמוֹפְתַיָא וִידָא תַקֶפְתָּא וּדְרָעָא מְרָמְמָא דִי אַפְּקָךְ יְיָ אֱלָהָךְ כֵּן יַעְבֵּד יְיָ אֱלָהָךְ לְכָל עַמְמַיָא דִי אַתְּ דָחֵל מִקֳדָמֵיהוֹן:
@9 וְאַף יָת עֲרָעִיתָא יְגָרֵי יְיָ אֱלָהָךְ בְּהוֹן עַד דְיֵבַדוּן דְאִשְׁתָּאָרוּ וּדְאִטַמָרוּ מֵקֳדָמָךְ:
@10 לָא תִתְּבַר מִקֳדָמֵיהוֹן אֲרֵי יְיָ אֱלָהָךְ שְׁכִנְתֵּהּ בֵּינָךְ אֱלָהָא רַבָּא וּדְחִילָא:
@11 וִיתָרַךְ יְיָ אֱלָהָךְ יָת עַמְמַיָא הָאִלֵין מִקֳדָמָךְ זְעֵר זְעֵר לָא תִכּוּל לְשֵׁצָי וּתְהוֹן בִּפְרִי עַ דִי לְמָא תִסְגֵּי עֲלָךְ חֵיוַת בָּרָא:
@12 וְיִמְסְרִנוּן יְיָ אֱלָהָךְ קֳדָמָךְ וִישַׁגֵשִׁנוּן שִׁגוּשׁ רַב עַד דְיִשְׁתֵּצוּן:
@13 וְיִמְסַר מַלְכֵיהוֹן בִּידָךְ וְתוֹבַד יָת שִׁמְהוֹן מִתְּחוֹת שְׁמַיָא לָא יִתְעַתַּד אֱנַשׁ קֳדָמָךְ עַד דִתְשֵׁיצֵי יָתְהוֹן:
@14 צַלְמֵי טַעֲוָתְהוֹן תּוֹקְדוּן בְּנוּרָא לָא תַחְמֵד כַּסְפָּא וְדַהֲבָא דִי עֲלֵיהוֹן וְתִסַב לָךְ דִילְמָא תִּתָּקַל בֵּהּ אֲרֵי מְרָחָקָא דַיְיָ אֱלָהָךְ הוּא:
@15 וְלָא תָעֵל דִמְרָחָק לְבֵיתָךְ וּתְהֵי חֶרְמָא כְּוָתֵהּ שַׁקָצָא תְשַׁקְצִנֵהּ וְרַחָקָא תְּרַחֲקִנֵהּ אֲרֵי חֶרְמָה הוּא:
@16 כָּל תַּפְקֶדְתָּא דִי אֲנָא מְפַקְדָךְ יוֹמָא דֵין תִּטְרוּן לְמֶעְבָּד בְּדִיל דְתֵיחוּן וְתִסְגוּן וְתֵיתוּן וְתֵירְתוּן יָת אַרְעָא דִי קַיִים יְיָ לַאֲבָהָתְכוֹן:
@17 וְתִדְכַּר יָת כָּל אָרְחָא דִי דַבְּרָךְ יְיָ אֱלָהָךְ דְנַן אַרְבְּעִין שְׁנִין בְּמַדְבְּרָא בְּדִיל לְעַנָיוּתָךְ לְנַסָיוּתָךְ לְמִדַע יָת דִי בְלִבָּךְ הֲתִטַר פִּקוּדוֹהִי אִם לָא:
@18 וְעַנְיָךְ וְאַכְפָּנָךְ וְאוֹכָלָךְ יָת מַנָא דִי לָא יְדַעְתְּ וְלָא יָדְעוּן אֲבָהָתָיךְ בְּדִיל לְאוֹדָעוּתָךְ אֲרֵי לָא עַל לַחְמָא בִלְחוֹדוֹהִי מִתְקַיַם אֱנָשָׁא אֲרֵי עַל כָּל אַפָּקוּת מֵימְרָא דַיְיָ יִתְקַיַם אֱנָשָׁא:
@19 כְּסוּתָךְ לָא אִבְלִיאַת מִנָךְ וּמְסָנָךְ לָא יְחֵפוּ דְנַן אַרְבְּעִין שְׁנִין:
@20 וְתִדַע עִם לִבָּךְ אֲרֵי כְּמָא דִי מְאַלֵף גַבְרָא יָת בְּרֵהּ יְיָ אֱלָהָךְ מְאַלֵף לָךְ:
@21 וְתִטַר יָת פִּקוּדַיָא דַיְיָ אֱלָהָךְ לִמְהַךְ בְּאָרְחַן דְתַקְנָן קֳדָמוֹהִי וּלְמִדְחַל יָתֵהּ:
@22 אֲרֵי יְיָ אֱלָהָךְ מַעֲלָךְ לְאַרְעָא טַבְתָא אַרְעָא נָגְדָא נַחֲלִין דְמַיִין מַבּוּעֵי עֵינַוָן וּתְהוֹמִין נָפְקִין בְּבִקְעָן וּבְטוּרִין:
@23 אַרְעָא חִטִּין וְסַעֲרִין וְגוּפְנִין וּתְאֵנִין וְרִמוֹנִין אַרְעָא דְזֵיתָהָא עָבְדִין מִשְׁחָא וְהִיא עָבְדָא דְבָשׁ:
@24 אַרְעָא דִי לָא בְעִצוּרִין (נ''א בְמִסְכֵּנוּ) תֵּיכוּל בַּהּ לַחֲמָא לָא תֶחְסַר כָּל מִדַעַם בַּהּ אַרְעָא דִי אַבְנָהָא פַרְזְלָא וּמִטוּרָהָא תִּפְסוּל נְחָשָׁא:
@25 וְתֵיכוּל וְתִשְׂבַּע וּתְבָרַךְ יָת יְיָ אֱלָהָךְ עַל אַרְעָא טַבְתָא דִיהַב לָךְ:
@26 אִסְתַּמַר לָךְ דִילְמָא תִתְנְשֵׁי יָת דַחַלְתָּא דַיְיָ אֱלָהָךְ בְּדִיל דְלָא לְמִטַר פִּקּוֹדוֹהִי וְדִינוֹהִי וּקְיָמוֹהִי דִי אֲנָא מְפַקְדָךְ יוֹמָא דֵין:
@27 דִילְמָא תֵיכוּל וְתִשְׂבַּע וּבָתִּין שַׁפִּירִין תִּבְנֵי וְתֵיתֵב:
@28 וְתוֹרָךְ וְעָנָךְ יִסְגוּן וְכַסְפָּא וְדַהֲבָא יִסְגֵא לָךְ וְכֹל דִי לָךְ יִסְגֵא:
@29 וִירִים לִבָּךְ וְתִנְשֵׁי יָת דַחַלְתָּא דַיְיָ אֱלָהָךְ דִי אַפְּקָךְ מֵאַרְעָא דְמִצְרַיִם מִבֵּית עַבְדוּתָא:
@30 דְדַבְּרָךְ בְּמַדְבְּרָא רַבָּא וּדְחִילָא אֲתַר חֵיוָן קָלָן וְעַקְרַבִּין וּבֵית צַחֲוָנָא אֲתַר דִי לֵית מַיָא דְאַפֵּק לָךְ מַיָא מִטִּנָרָא תַּקִיפָא:
@31 דְאוֹכָלָךְ מַנָא בְּמַדְבְּרָא דִי לָא יָדְעוּן אֲבָהָתָךְ בְּדִיל לְעַנָיוּתָךְ וּבְדִיל לְנַסָיוּתָךְ לְאוֹטָבָא לָךְ בְּסוֹפָךְ:
@32 וְתֵימַר בְּלִבָּךְ חֵילִי וּתְקֵף יְדִי קְנוֹ לִי יָת נִכְסַיָא הָאִלֵין:
@33 וְתִדְכַּר יָת יְיָ אֱלָהָךְ אֲרֵי הוּא יָהֵב לָךְ עֵצָה לְמִקְנֵי נִכְסִין בְּדִיל לְקַיָמָא יָת קְיָמֵהּ דִי קַיִים לְאֲבָהָתָךְ כְּיוֹמָא הָדֵין:
@34 וִיהֵי אִם מִנְשָׁאָה תִנְשֵׁי יָת דַחַלְתָּא דַיְיָ אֱלָהָךְ וּתְהַךְ בָּתַר טַעְוַת עַמְמַיָא וְתִפְלְחִנוּן וְתִסְגוּד לְהוֹן אַסְהֵדִית בְּכוֹן יוֹמָא דֵין אֲרֵי מֵיבַד תֵּיבְדוּן:
@35 כְּעַמְמַיָא דִי יְיָ מֹאבִיד מִקֳדָמֵיכוֹן כֵּן תֵּיבְדוּן חֳלַף דְלָא קַבֶּלְתּוּן בְּמֵימְרָא דַיְיָ אֱלָהֲכוֹן:
@36 שְׁמַע יִשְׂרָאֵל אַתְּ עָבֵר יוֹמָא דֵין יָת יַרְדְנָא לְמֵיעַל לְמֵירַת עַמְמִין רַבְרְבִין וְתַקִיפִין מִנָךְ קִרְוִין רַבְרְבָן וּכְרִיכָן עַד צֵית שְׁמַיָא:
@37 עַם רַב וְתַקִיף בְּנֵי גִבָּרַיָא דִי אַתְּ יְדַעַתְּ וְאַתְּ שְׁמַעְתְּ מָן יִכּוּל לְמֵיקַם קֳדָם בְּנֵי גִבָּרַיָא:
@38 וְתִדַע יוֹמָא דֵין אֲרֵי יְיָ אֱלָהָךְ הוּא דְעֲבַר קֳדָמָךְ מֵימְרֵהּ אֶשָׁא אָכְלָא הוּא יְשֵׁצִנוּן וְהוּא יְתָרֵכִנוּן קֳדָ מָךְ וּתְתָרֵ כִנוּן וְתוֹבְדִנוּן בִּפְרִיעַ כְּמָא דִי מַלִיל יְיָ לָךְ:
@39 לָא תֵימַר בְּלִבָּךְ בִּדְיִתְּבַר יְיָ אֱלָהָךְ יָתְהוֹן מִקֳדָמָךְ לְמֵימַר בְּזָכוּתִי אַעֲלַנִי יְיָ לְמֵירַת יָת אַרְעָא הָדָא וּבְחוֹבֵי עַמְמַיָא הָאִלֵין יְיָ מְתָרֶכְהוֹן מֵקֳדָמָךְ:
@40 לָא בְזָכוּתָךְ וּבְקַשִׁיטּוּת לִבָּךְ אַתְּ עָלֵל לְמֵירַת יָת אַרְעֲהוֹן אֲרֵי בְּחוֹבֵי עַמְמַיָא הָאִלֵין יְיָ אֱלָהָךְ מתָרֶכְהוֹן מִקָדָמָךְ וּבְדִיל לַאֲקָמָא יָת פִּתְגָמָא דִי קַיִים יְיָ לַאֲבָהָתָךְ לְאַבְרָהָם לְיִצְחָק וּלְיַעֲקֹב:
@41 וְתִדַע אֲרֵי לָא בְזָכוּתָךְ יְיָ אֱלָהָךְ יָהֵב לָךְ יָת אַרְעָא טַבְתָא הָדָא לְמֵירְתַהּ אֲרֵי עַם קְשֵׁי קְדַל אַתְּ:
@42 הֱוֵי דְכִיר לָא תִנְשֵׁי יָת דִי אַרְגֶזְתָּא קֳדָם יְיָ אֱלָהָךְ בְּמַדְבְּרָא לְמִן יוֹמָא דִי נְפַקְתָּא מֵאַרְעָא דְמִצְרַיִם עַד מֵיתֵיכוֹן עַד אַתְרָא הָדֵין מְסָרְבִין הֲוֵיתוּן קֳדָם יְיָ:
@43 וּבְחוֹרֵב אַרְגֶזְתּוּן קֳדָם יְיָ וַהֲוָה רְגַז מִן קֳדָם יְיָ בְּכוֹן לְשֵׁיצָאָה יַתְכוֹן:
@44 בְּמִסְקִי לְטוּרָא לְמִסַב לוּחֵי אַבְנַיָא לוּחֵי קְיָמָא דִי גְזַר יְיָ עִמְכוֹן וִיתֵבִית בְּטוּרָא אַרְבְּעִין יְמָמִין וְאַרְבְּעִין לֵילָוָן לַחֲמָא לָא אֲכָלִית וּמַיָא לָא אִשְׁתֵּיתִי:
@45 וִיהַב יְיָ לִי יָת תְּרֵין לוּחֵי אַבְנַיָא כְּתִיבִין בְּאֶצְבְּעָא דַיְיָ וַעֲלֵיהוֹן כְּכָל פִּתְגָמַיָא דִי מַלִיל יְיָ עִמְכוֹן בְּטוּרָא מִגוֹ אֶשָׁתָא בְּיוֹמָא דִקְהָלָא:
@46 וַהֲוָה מִסוֹף אַרְבְּעִין יְמָמִין וְאַרְבְּעִין לֵילָוָן יְהַב יְיָ לִי יָת תְּרֵין לוּחֵי אַבְנַיָא לוּחֵי קְיָמָא:
@47 וַאֲמַר יְיָ לִי קוּם חוּת בִּפְרִיעַ מִכָּא אֲרֵי חַבִּיל עַמָךְ דִי אַפֶּקְתָּא מִמִצְרָיִם סָטוּ בִּפְרִיעַ מִן אָרְחָא דִי פַקֶדְתִּנוּן עֲבָדוּ לְהוֹן מַתְּכָא:
@48 וַאֲמַר יְיָ לִי לְמֵימָר גְלֵי קֳדָמַי יָת עַמָא הָדֵין וְהָא עַם קְשֵׁי קְדַל הוּא:
@49 אַנַח בָּעוּתָךְ מִקֳדָמַי וֶאֱשֵׁצִנוּן וְאֶמְחֵי יָת שִׁמְהוֹן מִתְּחוֹת שְׁמַיָא וְאֶעְבֵּד יָתָךְ לְעַם תַּקִיף וְסַגִי מִנְהוֹן:
@50 וְאִתְפְּנֵיתִי וּנְחָתִית מִן טוּרָא וְטּוּרָא בָּעֵר בְּאֶשָׁתָא וּתְרֵין לוּחֵי קְיָמָא עַל תַּרְתֵּין יְדָי:
@51 וַחֲזֵיתִי וְהָא חַבְתּוּן קֳדָם יְיָ אֱלָהֲכוֹן עֲבַדְתּוּן לְכוֹן עֵגֶל מַתְּכָא סְטֵיתוּן בִּפְרִיעַ מִן אָרְחָא דִי פַקִיד יְיָ יָתְכוֹן:
@52 וַאֲחָדִית בִּתְרֵין לוּחַיָא וּרְמִיתִנוּן מֵעַל תַּרְתֵּין יְדָי וּתְבַרְתִּנוּן לְעֵינֵיכוֹן:
@53 וְאִשְׁתַּטָחִית קֳדָם יְיָ כְּקַדְמֵיתָא אַרְבְּעִין יְמָמִין וְאַרְבְּעִין לֵילָוָן לַחְמָא לָא אֲכָלִית וּמַיָא לָא אִשְׁתֵּיתִי עַל כָּל חוֹבֵיכוֹן דִי חַבְתּוּן לְמֶעְבַּד דְבִישׁ קֳדָם יְיָ לְאַרְגָזָא קֳדָמוֹהִי:
@54 אֲרֵי דְחֵלִית מִקָדָם רָגְזָא וְחֵמְתָא דִי רְגַז יְיָ עֲלֵיכוֹן לְשֵׁצָאָה יָתְכוֹן וְקַבִּיל יְיָ צְלוֹתִי אַף בְּזִמְנָא הַהִיא:
@55 וְעַל אַהֲרֹן הֲוָה רְגַז מִן קֳדָם יְיָ לַחֲדָא לְשֵׁצָיוּתֵהּ וְצַלֵיתִי אַף עַל אַהֲרֹן בְּעִדָנָא הַהִיא:
@56 וְיָת חוֹבָתְכוֹן דִי עֲבַדְתּוּן יָת עֶגְלָא נְסֵבִית וְאוֹקֵדִית יָתֵהּ בְּנוּרָא וְשָׁפִית יָתֵהּ בְּשׁוּפִינָא יָאוּת עַד דִי הֲוָה דַקִיק לְעַפְרָא וּרְמֵת יָת עַפְרֵהּ לְנַחֲלָא דְנָחֵת מִן טוּרָא:
@57 וּבִדְלֶקְתָּא וּבְנִסֵתָא וּבְקִבְרֵי דִמְשַׁאֲלֵי מַרְגְזִין הֲוֵיתוּן קֳדָם יְיָ:
@58 וְכַד שְׁלַח יְיָ יָתְכוֹן מֵרְקַם גֵיאָה לְמֵימַר סְקוֹ וְאַחֲסִינוּ יָת אַרְעָא דִי יְהָבִית לְכוֹן וְסָרֶבְתּוּן עַל גְזֵרַת מֵימְרָא דַיְיָ אֱלָהֲכוֹן וְלָא הֵימַנְתּוּן לֵהּ וְלָא קַבֶּלְתּוּן לְמֵימְרֵהּ:
@59 מְסָרְבִין הֲוֵיתוּן קֳדָם יְיָ מִיוֹמָא דִידָעִית יָתְכוֹן:
@60 וְאִשְׁתַּטָחִית קֳדָם יְיָ יָת אַרְבְּעִין יְמָמִין וְיָת אַרְבְּעִין לֵילָוָן דִי אִשְׁתַּטָחִית אֲרֵי אֲמַר יְיָ לְשֵׁצָאָה יָתְכוֹן:
@61 וְצַלֵיתִי קֳדָם יְיָ וַאֲמָרִית יְיָ אֱלֹהִים לָא תְחַבֵּל עַמָךְ וְאַחֲסַנְתָּךְ דִי פְרַקְתָּא בְּתָקְפָּךְ דִי אַפֶּקְתָּא מִמִצְרַיִם בִּידָא תַקִיפָא:
@62 אִדְכַר לְעַבְדָיךְ לְאַבְרָהָם לְיִצְחָק וּלְיַעֲקֹב לָא תִתְפְּנֵי לְקַשְׁיוּת עַמָא הָדֵין וּלְחוֹבֵיהוֹן וְלַחֲטָאֵיהוֹן:
@63 דִילְמָא יֵימְרוּן דָיְרֵי אַרְעָא דִי אַפֶּקְתָּנָא מִתַּמָן מִדְלֵית יוּכְלָא דַיְיָ לְאָעָלוּתְהוֹן לְאַרְעָא דִי מַלִיל לְהוֹן וּמִדְסָנֵי יָתְהוֹן אַפֵּקִנוּן לְקַטָלוּתְהוֹן בְּמַדְבְּרָא:
@64 וְאִנוּן עַמָךְ וְאַחֲסַנְתָּךְ דִי אַפֶּקְתָּא בְּחֵילָךְ רַבָּא וּבִדְרָעָךְ מְרָמְמָא:
@65 בְּעִדָנָא הַהִיא אֲמַר יְיָ לִי פְּסַל לָךְ תְּרֵין לוּחֵי אַבְנַיָא כְּקַדְמָאֵי וְסַק לָקֳדָמַי לְטּוּרָא וְתַעְבֵּד לָךְ אֲרוֹנָא דְאָעָא:
@66 וְאֶכְתּוֹב עַל לוּחַיָא יָת פִּתְגָמַיָא דִי הֲווֹ עַל לוּחַיָא קַדְמָאֵי דִי תְבַרְתָּא וּתְשַׁוִנוּן בַּאֲרוֹנָא:
@67 וַעֲבָדִית אֲרוֹנָא דְאָעֵי שִׁטִּין וּפְסָלִית תְּרֵין לוּחֵי אַבְנַיָא כְּקַדְמָאֵי וּסְלֵקִית לְטוּרָא וּתְרֵין לוּחַיָא בִּידִי:
@68 וּכְתַב עַל לוּחַיָא כִּכְתָבָא קַדְמָאָה יָת עַשְׂרָא פִתְגָמַיָא דִי מַלִיל יְיָ עִמְכוֹן בְּטוּרָא מִגוֹ אֶשְׁתָא בְּיוֹמָא דִקְהָלָא וִיהָבִנוּן יְיָ לִי:
@69 וְאִתְפְּנֵיתִי וּנְחָתִית מִן טוּרָא וְשַׁוֵיתִי יָת לוּחַיָא בַּאֲרוֹנָא דִי עֲבָדִית וַהֲווֹ תַמָן כְּמָא דִי פַקְדַנִי יְיָ:
@70 וּבְנֵי יִשְׂרָאֵל נְטָלוּ מִבְּאֵרוֹת בְּנֵי יַעֲקָן לְמוֹסֵרָה תַּמָן מִית אַהֲרֹן וְאִתְקְבַר תַּמָן וְשַׁמֵשׁ אֶלְעָזָר בְּרֵהּ תְּחוֹתוֹהִי:
@71 מִתַּמָן נְטָּלוּ לְגֻדְגֹד וּמִן גֻדְגֹד לְיָטְבָת אַרְעָא נָגְדָא נַחֲלִין דְמַיִין:
@72 בְּעִדָנָא הַהִיא אַפְרֵשׁ יְיָ יָת שִׁבְטָּא דְלֵוִי לְמִטַל יָת אֲרוֹן קְיָמָא דַיְיָ לְמֵיקַם קֳדָם יְיָ לְשַׁמָשׁוּתֵהּ וּלְבָרָכָא בִשְׁמֵהּ עַד יוֹמָא הָדֵין:
@73 עַל כֵּן לָא הֲּוָה לְלֵוִי חֳלָק וְאַחֲסָנָא עִם אֲחוֹהִי מַתְּנָן דִיהַב לֵהּ יְיָ אִנוּן אַחֲסַנְתֵּהּ כְּמָא דִי מַלִיל יְיָ אֱלָהָךְ לֵהּ:
@74 וַאֲנָא הֲוֵיתִי קָאֵם בְּטוּרָא כְּיוֹמִין קַדְמָאִין אַרְבְּעִין יְמָמִין וְאַרְבְּעִין לֵילָוָן וְקַבִּיל יְיָ צְלוֹתִי אַף בְּזִמְנָא הַהוּא לָא אָבֵי יְיָ לְחַבָּלוּתָךְ:
@75 וַאֲמַר יְיָ לִי קוּם זִיל לְמִטוּל קֳדָם עַמָא וְיֵעֲלוּן וְיֵרְתוּן יָת אַרְעָא דִי קַיֵמִית לַאֲבָהָתְהוֹן לְמִתַּן לְהוֹן:
@76 וּכְעַן יִשְׂרָאֵל מָה יְיָ אֱלָהָךְ תָּבַע מִנָךְ אֱלָהֵן לְמִדְחַל קֳדָם יְיָ אֱלָהָךְ לִמְהַךְ בְּכָל אָרְחָן דְתָקְנָן קֳדָמוֹהִי וּלְמִרְחַם יָתֵהּ וּלְמִפְלַח קֳדָם יְיָ אֱלָהָךְ בְּכָל לִבָּךְ וּבְכָל נַפְשָׁךְ:
@77 לְמִטַר יָת פִּקוֹדַיָא דַיְיָ וְיָת קְיָמוֹהִי דַאֲנָא מְפַקְדָךְ יוֹמָא דֵין לִדְיֵיטַב לָךְ:
@78 הָא דַיְיָ אֱלָהָךְ שְׁמַיָא וּשְׁמֵי שְׁמַיָא אַרְעָא וְכָל דִי בַהּ:
@79 לְחוֹד בַּאֲבָהָתָךְ צָבֵי יְיָ לְמִרְחַם יָתְהוֹן וְאִתִּרְעֵי בִּבְנֵיהוֹן בַּתְרֵיהוֹן בְּכוֹן מִכָּל עַמְמַיָא כְּיוֹמָא הָדֵין:
@80 וְתֶעְדוּן יָת טַפְשׁוּת לִבְּכוֹן וּקְדָלְכוֹן לָא תַקְשׁוּן עוֹד:
@81 אֲרֵי יְיָ אֱלָהֲכוֹן הוּא אֱלָהָא דַיָנִין וּמָרֵי מַלְכִין אֱלָהָא רַבָּא גִבָּרָא וּדְחִילָא דִי לֵית קֳדָמוֹהִי מִסַב אַפִּין וְאַף לָא לְקַבָּלָא שָׁחְדָא:
@82 עָבֵד דִין יִתַּם וְאַרְמְלָא וְרָחֵם גִיוֹרָא לְמִתַּן לֵהּ מְזוֹנָא וּכְסוּ:
@83 וְתִרְחֲמוּן יָת גִיוֹרָא אֲרֵי דַיָרִין הֲוֵיתוּן בְּאַרְעָא דְמִצְרָיִם:
@84 יָת יְיָ אֱלָהָךְ תִּדְחַל וְקָדָמוֹהִי תִפְלָח וּלְדַחַלְתֵּהּ תִּקְרַב וּבִשְׁמֵהּ תְּקַיַם:
@85 הוּא תֻשְׁבַּחְתָּךְ וְהוּא אֱלָהָךְ דַעֲבַד עִמָךְ יָת רַבְרְבָתָא וְיָת חֲסִינָתָא הָאִלֵין דִי חֲזוֹ עֵינָיךְ:
@86 בְּשַׁבְעִין נַפְשָׁן נְחָתוּ אֲבָהָתָךְ לְמִצְרָיִם וּכְעַן שַׁוְיָךְ יְיָ אֱלָהָךְ כְּכוֹכְבֵי שְׁמַיָא לְמִסְגֵי:
@87 וְתִרְחַם יָת יְיָ אֱלָהָךְ וְתִטַּר מַטְרַת מֵימְרֵהּ וּקְיָמוֹהִי וְדִינוֹהִי וּפִקוֹדוֹהִי כָּל יוֹמַיָא:
@88 וְתִדְעוּן יוֹמָא דֵין אֲרֵי לָא יָת בְּנֵיכוֹן דִי לָא יְדָעוּ וְדִי לָא חֲזוֹ יָת אֻלְפָנָא דַיְיָ אֱלָהֲכוֹן יָת רְבוּתֵהּ יָת יְדֵהּ תַּקִיפָא וּדְרָעֵהּ מְרָמְמָא:
@89 וְיָת אַתְוָתֵהּ וְיָת עוֹבָדוֹהִי דִי עֲבַד בְּגוֹ מִצְרָיִם לְפַרְעֹה מַלְכָּא דְמִצְרַיִם וּלְכָל אַרְעֵהּ:
@90 וְדִי עֲבַד לְמַשִׁרְיַת מִצְרַיִם לְסוּסְוָתֵהּ וְלִרְתִיכוֹהִי דִי אַטִיף יָת מֵי יַמָא דְסוּף עַל אַפֵּיהוֹן בְּמִרְדָפְהוֹן בַּתְרֵיכוֹן וְאוֹבָדִנוּן יְיָ עַד יוֹמָא הָדֵין:
@91 וְדִי עֲבַד לְכוֹן בְּמַדְבְּרָא עַד מֵיתֵיכוֹן עַד אַתְרָא הָדֵין:
@92 וְדִי עֲבַד לְדָתָן וְלַאֲבִירָם בְּנֵי אֱלִיאָב בַּר רְאוּבֵן דִי פְתָחַת אַרְעָא יָת פּוּמַהּ וּבְלָעָתְנוּן וְיָת אֱנַשׁ בָּתֵּיהוֹן וְיָת מַשְׁכְּנֵיהוֹן וְיָת כָּל יְקוּמָא דִי עִמְהוֹן בְּגוֹ כָּל יִשְׂרָאֵל:
@93 אֲרֵי עֵינֵיכוֹן חֲזָאָן יָת כָּל עוֹבָדָא דַיְיָ רַבָּא דִי עֲבָד:
@94 וְתִטְרוּן יָת כָּל תַּפְקֶדְתָּא דִי אֲנָא מְפַקְדָךְ יוֹמָא דֵין בְּדִיל דְתִתְקְפוּן וְתֵעֲלוּן וְתֵירְתוּן יָת אַרְעָא דִי אַתּוּן עָבְרִין תַּמָן לְמֵירְתַהּ:
@95 וּבְדִיל דְתוֹרְכוּן יוֹמִין עַל אַרְעָא דִי קַיִים יְיָ לַאֲבָהָתְכוֹן לְמִתַּן לְהוֹן וְלִבְנֵיהוֹן אַרְעָא עָבְדָא חֲלַב וּדְבָשׁ:
@96 אֲרֵי אַרְעָא דִי אַתְּ עָלֵל לְתַמָן לְמֵירְתַהּ לָא כְאַרְעָא דְמִצְרַיִם הִיא דִי נְפַקְתּוּן מִתַּמָן דִי תִזְרַע יָת זַרְעָךְ וּמַשְׁקַת לֵהּ בְּרַגְלָךְ כְּגִנְתָא יַרְקָא:
@97 וְאַרְעָא דִי אַתּוּן עָבְרִין תַּמָן לְמֵירְתַהּ אֲרַע טוּרִין וּבִקְעָן לִּמְטַּר שְׁמַיָא תִּשְׁתֵּי מַיָא:
@98 אַרְעָא דַיְיָ אֱלָהָךְ תָּבַע יָתַהּ תְּדִירָא עֵינֵי דַיְיָ אֱלָהָךְ בַּהּ מֵרֵישָׁא דְשַׁתָּא וְעַד סוֹפָא דְשַׁתָּא:
@99 וִיהֵי אִם קַבָּלָא תְקַבְּלוּן לְפִקוּדַי דִי אֲנָא מְפַקֵד יָתְכוֹן יוֹמָא דֵין לְמִרְחַם יָת יְיָ אֱלָהֲכוֹן וּלְמִפְלַח קֳדָמוֹהִי בְּכָל לִבְּכוֹן וּבְכָל נַפְשְׁכוֹן:
@100 וְאֶתֵּן מְטַר אַרְעֲכוֹן בְּעִדָנֵהּ בַּכִּיר וְלַקִישׁ וְתִכְנוֹשׁ עִבוּרָךְ וְחַמְרָךְ וּמִשְׁחָךְ:
@101 וְאֶתֵּן עִשְׂבָּא בְחַקְלָךְ לִבְעִירָךְ וְתֵיכוּל וְתִשְׂבָּע:
@102 אִסְתַּמָרוּ לְכוֹן דִילְמָא יִטְעוּן לִבְּכוֹן וְתִסְטוּן וְתִפְלְחוּן לְטַעֲוַת עַמְמַיָא וְתִסְגְדוּן לְהוֹן:
@103 וְיִתְקוֹף רָגְזָא דַיְיָ בְּכוֹן וְיֵחוֹד יָת שְׁמַיָא וְלָא יְהֵי מִטְרָא וְאַרְעָא לָא תִתֵּן יָת עֲלַלְתַּהּ וְתֵיבְדוּן בִּפְרִיעַ מֵעַל אַרְעָא טַבְתָא דַיְיָ יָהֵב לְכוֹן:
@104 וּתְשַׁווּן יָת פִּתְגָמַי אִלֵין עַל לִבְּכוֹן וְעַל נַפְשְׁכוֹן וְתִקְטְרוּן יָתְהוֹן לְאָת עַל יֶדְכוֹן וִיהוֹן לִתְפִלִין בֵּין עֵינֵיכוֹן:
@105 וְתַלְפוּן יָתְהוֹן יָת בְּנֵיכוֹן לְמַלָלָא בְהוֹן בְּמִתְּבָךְ בְּבֵיתָךְ וּבִמְהָכָךְ בְּאָרְחָא וּבְמִשְׁכְּבָךְ וּבִמְקִימָךְ:
@106 וְתִכְתְּבִנוּן עַל מְזוּזְיָן וְתִקְבְּעִנוּן בְּסִפֵּי בֵיתָךְ וּבְתַרְעָיךְ:
@107 בְּדִיל דְיִסְגוּן יוֹמֵיכוֹן וְיוֹמֵי בְנֵיכוֹן עַל אַרְעָא דִי קַיִים יְיָ לַאֲבָהָתְכוֹן לְמִתַּן לְהוֹן כְּיוֹמֵי שְׁמַיָא עַל אַרְעָא:
@108 אֲרֵי אִם מִטַר תִּטְרוּן יָת כָּל תַּפְקֶדְתָּא הָדָא דִי אֲנָא מְפַקֵד יָתְכוֹן לְמֶעְבְּדַהּ לְמִרְחַם יָת יְיָ אֱלָהֲכוֹן לִמְהַךְ בְּכָל אָרְחָן דְתַקְנָן קֳדָמוֹהִי וּלְאִתְקְרָבָא לְדַחַלְתֵּהּ:
@109 וִיתָרֵךְ יְיָ יָת כָּל עַמְמַיָא הָאִלֵין מִקֳדָמֵיכוֹן וְתֵירְתוּן עַמְמִין רַבְרְבִין וְתַקִיפִין מִנְכוֹן:
@110 כָּל אַתְרָא דִי תִדְרוֹךְ פַּרְסַת רַגְלְכוֹן בֵּהּ דִלְכוֹן יְהֵי מִן מַדְבְּרָא וְלִבְנָן מִן נַהֲרָא נְהַר פְּרָת וְעַד יַמָא מַעַרְבָא יְהֵי תְחוּמְכוֹן:
@111 לָא יִתְעַתַּד אֱנָשׁ קֳדָמֵיכוֹן דַחֲלָתְכוֹן וְאֵימָתְכוֹן יִתֵּן יְיָ אֱלָהֲכוֹן עַל אַפֵּי כָל אַרְעָא דִי תִדְרְכוּן בַּהּ כְּמָה דִי מַלִיל לְכוֹן: ססס:

@1 **והיה עקב תשמעון.** אם המצות הקלות שאדם דש בעקביו תשמעון: **ושמר ה'** וגו' **.** ישמור לך הבטחתו:
@2 **שגר אלפיך.** ולדי בקרך, שהנקבה משגרת ממעיה: **ועשתרת צאנך.** מנחם פרש אבירי בשן (תהלים כב, יג) , מבחר הצאן. כמו (בראשית יד, ה) עשתרות קרנים, לשון חזק. ואונקלוס תרגם ועדרי ענך. ורבותינו אמרו למה נקרא שמם עשתרות שמעשירות את בעליהן:
@3 **עקר.** שאינו מוליד:
@6 **כי תאמר בלבבך.** על כרחך לשון דלמא הוא, שמא תאמר בלבבך מפני שהם רבים לא אוכל להורישם, אל תאמר כן, לא תירא מהם. ולא יתכן לפרשו באחת משאר לשונות של 'כי', שיפול עליו שוב לא תירא מהם:
@8 **המסות.** נסיונות: **והאותות.** כגון (שמות ד, ג) ויהי לנחש, (שמות ד, ט) והיו לדם ביבשת: **והמופתים.** המכות המפלאות: **והיד החזקה.** זה הדבר: **והזרוע הנטויה.** זה החרב של מכת בכורות:
@9 **הצרעה.** מין שרץ העוף, שהיתה זורקת בהם מרה ומסרסתן ומסמאה את עיניהם בכל מקום שהיו נסתרים שם:
@11 **פן תרבה עליך חית השדה.** והלא אם עושין רצונו של מקום אין מתיראין מן החיה, שנאמר (איוב ה, כג) וחית השדה השלמה לך, אלא גלוי היה לפניו שעתידין לחטוא:
@12 **והמם.** נקוד קמ''ץ כלו, לפי שאין מ''ם אחרונה מן היסוד, והרי הוא כמו והם אותם. אבל (ישעי' כח, כח) והמם גלגל עגלתו, כלו יסוד. לפיכך חציו קמ''ץ וחציו פת''ח, כשאר פעל של שלש אותיות:
@16 **כל המצוה.** כפשוטו. ומדרש אגדה אם התחלת במצוה גמור אותה, שאינה נקראת אלא על שם הגומרה, שנאמר (יהושע כד, לב) ואת עצמות יוסף אשר העלו בני ישראל ממצרים קברו בשכם, והלא משה לבדו נתעסק בהם להעלותם, אלא לפי שלא הספיק לגמרה וגמרוה ישראל, נקראת על שמם:
@17 **התשמר מצותיו.** שלא תנסהו ולא תהרהר אחריו:
@19 **שמלתך לא בלתה.** ענני כבוד היו שפים בכסותם ומגהצים אותם כמין כלים מגוהצים, ואף קטניהם כמו שהיו גדלים היה גדל לבושן עמהם, כלבוש הזה של חומט שגדל עמו: **לא בצקה.** לא נפחה כבצק, כדרך הולכי יחף שרגליהם נפוחות:
@23 **זית שמן.** זיתים העושים שמן:
@36 **גדלים ועצמים ממך.** אתה עצום, והם עצומים ממך:
@39 **אל תאמר בלבבך.** צדקתי ורשעת הגוים גרמו:
@40 **לא בצדקתך** וגו' **אתה בא לרשת** וגו' **כי ברשעת הגוים.** הרי כי משמש בלשון אלא:
@44 **ואשב בהר.** אין ישיבה אלא לשון עכבה:
@46 **לחת.** לחת כתיב, ששתיהם שוות:
@53 **ואתנפל לפני ה' כראשנה ארבעים יום.** שנאמר (שמות לב, ל) ועתה אעלה אל ה' אולי אכפרה. באותה עליה נתעכבתי ארבעים יום. נמצאו כלים בעשרים ותשעה באב. שהוא עלה בשמונה עשר בתמוז, בו ביום נתרצה הקדוש ברוך הוא לישראל ואמר לו למשה (דברים י, א) פסל לך שני לוחת, עשה עוד ארבעים יום, נמצאו כלים ביום הכפורים. בו ביום נתרצה הקדוש ברוך הוא לישראל בשמחה ואמר לו למשה (במדבר יד, כ) סלחתי כדברך. לכך הקבע למחילה ולסליחה. ומנין שנתרצה ברצון שלם, שנאמר בארבעים של לוחות אחרונות ואנכי עמדתי בהר כימים הראשונים (דברים י, י) , מה הראשונים ברצון אף אחרונים ברצון, אמור מעתה אמצעיים היו בכעס:
@55 **ובאהרן התאנף ה'.** לפי ששמע לכם: **להשמידו.** זה כלוי בנים. וכן הוא אומר (עמוס ב, ט) ואשמיד פריו ממעל: **ואתפלל גם בעד אהרן.** והועילה תפלתי לכפר מחצה, ומתו שנים ונשארו השנים:
@56 **טחון.** לשון הוה כמו (בראשית כו, יג) הלוך וגדל:
@60 **ואתנפל** וגו' **.** אלו הן עצמם האמורים למעלה (פסוק יח) וכפלן כאן, לפי שכתוב כאן סדר תפלתו, שנאמר (פסוק כו) ה' אלהים אל תשחת עמך וגו' :
@65 **בעת ההוא.** לסוף ארבעים יום נתרצה לי ואמר לי פסל לך, ואחר כך ועשית לך ארון עץ, ואני עשיתי ארון תחלה, שכשאבוא והלחות בידי היכן אתנם. ולא זה הוא הארון שעשה בצלאל, שהרי משכן לא נתעסקו בו עד לאחר יום הכפורים, כי ברדתו מן ההר צוה להם על מלאכת המשכן, ובצלאל עשה משכן תחלה ואחר כך ארון וכלים, נמצא זה ארון אחר היה. וזהו שהיה יוצא עמהם למלחמה. ואותו שעשה בצלאל לא יצא למלחמה אלא בימי עלי, ונענשו עליו ונשבה:
@70 **ובני ישראל נסעו מבארות בני יעקן מוסרה.** מה ענין זה לכאן. ועוד, וכי מבארות בני יעקן נסעו למוסרה, והלא ממוסרות באו לבני יעקן, שנאמר (במדבר לג, לא) ויסעו ממוסרות וגו' . ועוד, שם מת אהרן, והלא בהר ההר מת, צא וחשוב ותמצא שמונה מסעות ממוסרה להר ההר. אלא, אף זו מן התוכחה, ועוד זאת עשיתם כשמת אהרן בהר ההר לסוף ארבעים שנה ונסתלקו ענני כבוד, יראתם לכם ממלחמת מלך ערד ונתתם ראש לחזור למצרים, וחזרתם לאחוריכם שמונה מסעות עד בני יעקן ומשם למוסרה, שם נלחמו בכם בני לוי והרגו מכם ואתם מהם, עד שהחזירו אתכם בדרך חזרתכם, ומשם חזרתם הגדגדה הוא חור הגדגד:
@71 **ומן הגדגדה** וגו' **.** ובמוסרה עשיתם אבל כבד על מיתתו של אהרן שגרמה לכם זאת, ונדמה לכם כאלו מת שם. וסמך משה תוכחה זו לשבירת הלוחות, לומר שקשה מיתתן של צדיקים לפני הקדוש ברוך הוא, כיום שנשתברו בו הלוחות. ולהודיעך שהקשה לו מה שאמרו (במד' יד, ד) נתנה ראש לפרוש ממנו, כיום שעשו בו את העגל:
@72 **בעת ההוא הבדיל ה'** וגו' **.** מוסב לענין הראשון: **בעת ההוא.** בשנה הראשונה לצאתכם ממצרים וטעיתם בעגל ובני לוי לא טעו, הבדילם המקום מכם. וסמך מקרא זה לחזרת בני יעקן לומר שאף בזו לא טעו בה בני לוי, אלא עמדו באמונתם: **לשאת את ארון.** הלוים: **לעמד לפני ה' לשרתו ולברך בשמו.** הכהנים, והוא נשיאת כפים:
@73 **על כן לא היה ללוי חלק.** לפי שהבדלו לעבודת מזבח ואינן פנויין לחרוש ולזרוע: **ה' הוא נחלתו.** נוטל פרס מזמן מבית המלך:
@74 **ואנכי עמדתי בהר.** לקבל הלוחות האחרונות. ולפי שלא פרש למעלה כמה עמד בהר בעליה אחרונה זו, חזר והתחיל בה: **כימים הראשונים.** של לוחות הראשונות, מה הם ברצון אף אלו ברצון. אבל האמצעיים שעמדתי שם להתפלל עליכם היו בכעס:
@75 **ויאמר ה' אלי** וגו' **.** אף על פי שסרתם מאחריו וטעיתם בעגל, אמר לי (שמות לב, לד) לך נחה את העם:
@76 **ועתה ישראל.** אף על פי שעשיתם כל זאת, עודנו רחמיו וחבתו עליכם, ומכל מה שחטאתם לפניו אינו שואל מכם כי אם ליראה וגו' : **כי אם ליראה** וגו' **.** רבותינו דרשו מכאן, הכל בידי שמים חוץ מיראת שמים:
@77 **לשמר את מצות ה'.** ואף היא לא לחנם, אלא לטוב לך, שתקבלו שכר:
@78 **הן לה' אלהיך.** הכל, ואף על פי כן רק באבותיך חשק ה' מן הכל:
@79 **בכם.** כמו שאתם רואים אתכם חשוקים מכל העמים היום הזה:
@80 **ערלת לבבכם.** אוטם לבבכם וכסויו:
@81 **ואדני האדנים.** לא יוכל שום אדון להציל אתכם מידו: **לא ישא פנים.** אם תפרקו עלו: **ולא יקח שחד.** לפיסו בממון:
@82 **עשה משפט יתום ואלמנה.** הרי גבורה, ואצל גבורתו אתה מוצא ענותנותו: **ואהב גר לתת לו לחם ושמלה.** ודבר חשוב הוא זה, שכל עצמו של יעקב אבינו על זה נתפלל, (בראשית כח, כ) ונתן לי לחם לאכל ובגד ללבש:
@83 **כי גרים הייתם.** מום שבך אל תאמר לחברך:
@84 **את ה' אלהיך תירא.** ותעבוד לו ותדבק בו, ולאחר שיהיו בך כל המדות הללו, אז בשמו תשבע:
@88 **וידעתם היום.** תנו לב לדעת ולהבין ולקבל תוכחתי: **כי לא את בניכם.** אני מדבר עכשיו שיוכלו לומר אנו לא ידענו ולא ראינו בכל זה:
@92 **בקרב כל ישראל.** כל מקום שהיה אחד מהם בורח, הארץ נבקעת מתחתיו ובולעתו, אלו דברי רבי יהודה. אמר לו רבי נחמיה, והלא כבר נאמר (במדבר טז, לב) ותפתח הארץ את פיה, ולא פיותיה. אמר לו, ומה אני מקים בקרב כל ישראל. אמר לו שנעשית הארץ מדרון כמשפך, וכל מקום שהיה אחד מהם [בורח] , היה מתגלגל ובא עד מקום הבקיעה: **ואת כל היקום אשר ברגליהם.** זה ממונו של אדם שמעמידו על רגליו:
@93 **כי עיניכם הראת.** מוסב על מקרא האמור למעלה, (פסוק ב) כי לא את בניכם אשר לא ידעו וגו' כי אם עמכם אשר עיניכם הרואות וגו' :
@96 **לא כארץ מצרים הוא.** אלא טובה המנה. ונאמרה הבטחה זו לישראל ביציאתם ממצרים, שהיו אומרים שמא לא נבוא אל ארץ טובה ויפה כזו. יכול בגנותה הכתוב מדבר, וכך אמר להם, לא כארץ מצרים היא, אלא רעה המנה, תלמוד לומר (במדבר יג, כב) וחברון שבע שנים נבנתה וגו' , אדם אחד בנאן, וחם בנה צוען למצרים בנו, וחברון לכנען. דרך ארץ אדם בונה את הנאה ואחר כך בונה את הכעור שפסלתו של ראשון, הוא נותן בשני. ובכל מקום, החביב קודם. הא למדת שחברון יפה מצוען, ומצרים משבחת מכל הארצות, שנאמר (בראשית יג, י) כגן ה' כארץ מצרים, וצוען שבח מצרים היא, שהיתה מקום מלכות, שכן הוא אומר (ישעיה ל, ד) כי היו בצוען שריו. וחברון פסלתה של ארץ ישראל, לכך הקצוה לקבורת מתים, ואף על פי כן היא יפה מצוען. ובמסכת כתבות (קיב, א) דרשו בענין אחר, אפשר אדם בונה בית לבנו הקטן ואחר כך לבנו הגדול, אלא שמבנה על אחד משבעה בצוען: **אשר יצאתם משם.** אפלו ארץ רעמסס [וארץ גושן] אשר ישבתם בה והיא במיטב ארץ מצרים שנאמר (בראשית מז, יא) במיטב הארץ וגו' , אף היא אינה כארץ ישראל: **והשקית ברגלך.** ארץ מצרים היתה צריכה להביא מים מנילוס ברגלך ולהשקותה וצריך אתה לנדד משינתך ולעמול, והנמוך שותה ולא הגבוה, ואתה מעלה המים מן הנמוך לגבוה. אבל זו (פסוק יא) למטר השמים תשתה מים. אתה ישן על מטתך, והקדוש ברוך הוא משקה נמוך וגבוה, גלוי ושאינו גלוי, כאחת: **כגן הירק.** שאין די לו בגשמים ומשקין אותו ברגל ובכתף:
@97 **ארץ הרים ובקעת.** משבח ההר מן המישור, שהמישור, בבית כור אתה זורע כור, אבל ההר בבית כור ממנו חמשת כורין, ארבע מארבע שפועיו, ואחד בראשו: **ובקעת.** הן מישור:
@98 **אשר ה' אלהיך דרש אתה.** והלא אף כל הארצות הוא דורש, שנאמר (איוב לח, כו) להמטיר על ארץ לא איש, אלא כביכול אינו דורש אלא אותה, ועל ידי אותה דרישה שדורשה דורש את כל הארצות עמה: **תמיד עיני ה' אלהיך בה.** לראות מה היא צריכה ולחדש לה גזרות, עתים לטובה עתים לרעה וכו' , כדאיתא בראש השנה (יז, ב) : **מרשית השנה.** מראש השנה נדון מה יהא בסופה:
@99 **והיה אם שמע.** והיה, מוסב על האמור למעלה, (פסוק יא) למטר השמים תשתה מים: **והיה אם שמע תשמעו.** אם שמע בישן תשמעו בחדש. וכן (דברים ח, יט) והיה אם שכח תשכח, אם התחלת לשכח, סופך שתשכח כלה, שכן כתיב במגלה אם תעזבני יום, יומים אעזבך [ במגילת חסידים ] (ספרי מח) : **מצוה אתכם היום.** שיהיו עליכם חדשים, כאלו שמעתם בו ביום: **לאהבה את ה'.** שלא תאמר הרי אני לומד בשביל שאהיה עשיר, בשביל שאקרא רב, בשביל שאקבל שכר. אלא כל מה שתעשו עשו מאהבה וסוף הכבוד לבא: **ולעבדו בכל לבבכם.** עבודה שהיא בלב. וזו היא תפלה, שהתפלה קרויה עבודה, שנאמר (דניאל ו, יז) אלהך די אנת פלח לה בתדירא, וכי יש פלחן בבבל, אלא על שהיה מתפלל, שנאמר (שם ו, יא) וכוין פתיחן לה וגו' . וכן בדוד הוא אומר (תהלים קמא, ב) תכון תפלתי קטרת לפניך: **בכל לבבכם ובכל נפשכם.** והלא כבר הזהיר על כך (דברים ו, ה) בכל לבבך ובכל נפשך, אלא, אזהרה ליחיד אזהרה לצבור:
@100 **ונתתי מטר ארצכם.** עשיתם מה שעליכם, אף אני אעשה מה שעלי: **בעתו.** בלילות שלא יטריחו אתכם. דבר אחר בעתו, בלילי שבתות שהכל מצויין בבתיהם: **יורה.** היא רביעה הנופלת לאחר הזריעה שמרוה את הארץ ואת הזרעים: **ומלקוש.** רביעה היורדת סמוך לקציר למלאות התבואה בקשיה. ולשון מלקוש, דבר המאוחר. כדמתרגמינן (בראשית ל, מב) והיה העטופים ללבן, לקישיא. דבר אחר לכך נקראת מלקוש שיורדת על המלילות ועל הקשין: **ואספת דגנך.** אתה תאספנו אל הבית ולא אויביך. כענין שנאמר (ישעי' סב, ח. ט) אם אתן את דגנך וגו' כי מאספיו יאכלהו, ולא כענין שנאמר (שופטים ו, ג) והיה אם זרע ישראל וגו' :
@101 **ונתתי עשב בשדך.** שלא תצטרך להוליכה למדבריות. דבר אחר שתהיה גוזז תבואתך כל ימות הגשמים ומשליך לפני בהמתך ואתה מונע ידך ממנה שלשים יום קודם לקציר ואינה פוחתת מדגנה: **ואכלת ושבעת.** הרי זו ברכה אחרת, שתהא ברכה מצויה בפת בתוך המעים:
@102 **השמרו לכם.** כיון שתהיו אוכלים ושבעים, השמרו לכם שלא תבעטו, שאין אדם מורד בהקדוש ברוך הוא אלא מתוך שביעה, שנאמר (דברים ח, יב. יד) פן תאכל ושבעת ובקרך וצאנך ירבין, מה הוא אומר אחריו, ורם לבבך ושכחת: **וסרתם.** לפרוש מן התורה ומתוך כך ועבדתם אלהים אחרים. שכיון שאדם פורש מן התורה הולך ומדבק בעבודה זרה. וכן דוד אמר (שמואל א' כו, יט) כי גרשוני היום מהסתפח בנחלת ה' לאמר לך עבד וגו' , ומי אמר לו כן, אלא כיון שאני מגרש מלעסוק בתורה, הריני קרוב לעבוד אלהים אחרים: **אלהים אחרים.** שהם אחרים לעובדיהם, צועק אליו ואינו עונהו, נמצא עשוי לו כנכרי:
@103 **את יבולה.** אף מה שאתה מוביל לה, כענין שנאמר (חגי א, ו) זרעתם הרבה והבא מעט: **ואבדתם מהרה.** על כל שאר היסורין אגלה אתכם מן האדמה, שגרמה לכם לחטוא. משל למלך ששלח בנו לבית המשתה והיה יושב ומפקידו [ומפקדו] אל תאכל יותר מצרכך שתבא נקי לביתך, ולא השגיח הבן ההוא. אכל ושתה יותר מצרכו והקיא וטנף את כל בני המסבה. נטלוהו בידיו וברגליו וזרקוהו אחורי פלטרין [פלטין] : **מהרה.** איני נותן לכם ארכא. ואם תאמרו והלא נתנה ארכא לדור המבול, שנאמר (בראשית ו, ג) והיו ימיו מאה ועשרים שנה, דור המבול לא היה להם ממי ללמוד ואתם יש לכם ממי ללמוד:
@104 **ושמתם את דברי.** אף לאחר שתגלו היו מצינים במצות, הניחו תפלין, עשו מזוזות כדי שלא יהיו לכם חדשים כשתחזרו. וכן הוא אומר (ירמיה לא, כ) הציבי לך צינים:
@105 **לדבר בם.** משעה שהבן יודע לדבר, למדהו תורה צוה לנו משה (דברים לג, ד) , שיהא זה למוד דבורו. מכאן אמרו, כשהתינוק מתחיל לדבר, אביו מסיח עמו בלשון הקדש ומלמדו תורה, ואם לא עשה כן הרי הוא כאלו קוברו, שנאמר ולמדתם אתם את בניכם לדבר בם וגו' למען ירבו ימיכם וימי בניכם:
@107 **למען ירבו ימיכם וימי בניכם.** אם עשיתם כן ירבו, ואם לאו לא ירבו, שדברי תורה נדרשין מכלל לאו הן, ומכלל הן לאו: **לתת להם.** לתת לכם אין כתיב כאן, אלא לתת להם, מכאן נמצינו למדים תחית המתים מן התורה:
@108 **שמר תשמרון.** אזהרת שמירות הרבה להזהר בתלמודו שלא ישתכח: **ללכת בכל דרכיו.** הוא רחום ואתה תהא רחום, הוא גומל חסדים ואתה גמול חסדים: **ולדבקה בו.** אפשר לומר כן, והלא אש אוכלה הוא, אלא הדבק בתלמידים ובחכמים ומעלה אני עליך כאלו נדבקת בו:
@109 **והוריש ה'.** עשיתם מה שעליכם אף אני אעשה מה שעלי: **ועצמים מכם.** אתם גבורים, והם גבורים מכם, שאם לא שישראל גבורים, מה השבח שמשבח את האמוריים לומר ועצמים מכם, אלא אתם גבורים משאר אמות והם גבורים מכם:
@111 **לא יתיצב איש** וגו' **.** אין לי אלא איש, אמה ומשפחה ואשה בכשפיה מנין, תלמוד לומר לא יתיצב מכל מקום. אם כן מה תלמוד לומר איש, אפלו כעוג מלך הבשן: **פחדכם ומוראכם.** והלא פחד הוא מורא, אלא פחדכם על הקרובים ומוראכם על הרחוקים. פחד לשון בעיתת פתאום. מורא לשון דאגה מימים רבים: **כאשר דבר לכם.** והיכן דבר (שמות כג, כז) את אימתי אשלח לפניך וגו' :

@1 **עקב** . כמו בעבור וכן עקב אשר שמע אברהם בקולי (בראשית כו ה) וכתב רש"י אם המצות הקלות שאדם דש בעקביו תשמעון ישמור לך השם הבטחתו והזכיר הכתוב המשפטים אולי יזהיר במשפטים הקלים כדיני ממונות שלא יבזו אותם והמפרשים אמרו כי טעם "עקב" שכר באחרית וכן בשמרם עקב רב (תהלים יט יב) יאמר והיה אחרית תשמעון המשפטים ותשמרו אותם שישמר השם לך את הברית והחסד ואהבך ונכון הוא כי יקראו בלשון הקדש תחלת כל דבר בלשון "ראש" כענין ראש דברך אמת (שם קיט קס) וכן גדול הדור ראש העם (במדבר כה ד) והמשובח ראש בשמים (שיר השירים ד יד) וכן יקראו אחרית כל דבר "עקב" כי הלשון יתפוס דמיונו באדם והראש תחלה והעקב בו אחרית וסוף וכן יאמר הכתוב (להלן כח יג מד) לראש ולזנב לדמיון גוף בהמה ואונקלוס תרגם חלף כמו חלף עבודתכם (במדבר יח לא) עשאו לשון סבוב נגזר מן והיה העקוב למישור (ישעיהו מ ד) הדרך המעוקל ההולך סביב סביב וכן עקובה מדם (הושע ו ח) מסובבת ומוקפת יאמר והיה סבת שמעכם המשפטים ועשותכם אותם שישמור השם לכם בריתו ויפה פירש ודומה לזה בגלל הדבר הזה (להלן טו י) בסבתו מלשון וגללו את האבן (בראשית כט ג) וכן על דעתי כל לשון עקיבה גלגול וסבוב עקוב הלב (ירמיהו יז ט) ויעקבני זה פעמים (בראשית כז לו) ויהוא עשה בעקבה (מלכים ב י יט) ענין גלגולין וסבות ולכן יקראו יעקב "ישורון" כי היפך העקוב מישור וכן אחורי הרגל שנקרא עקב וידו אוחזת בעקב עשו (בראשית כה כו) יקראנו כן בעבור היותו מעוגל כאשר יקרא הלשון אמצע היד והרגל "כפות" בעבור היותם כמו כפות הזהב ומורגל הוא בלשון כמו שאמרו בספרי (ברכה ב) מימינו אש דת למו (להלן לג ב) כשהיה יוצא הדבור מפי הקב"ה היה יוצא דרך ימינו של קדש לשמאלן של ישראל ועוקב את מחנה ישראל שנים עשר מיל על שנים עשר מיל כלומר מקיף וכן לשונם (ב"ק קיג) באים עליו בעקיפין בסבות וגלגולין כמו עקיבין ששתי האותיות האלה שוות להן כאשר פרשתי כבר (ויקרא יט כ) והזכיר את המשפטים האלה להזהיר מאד במשפטים כי לא יהיה עם רב כלו נזהר במצות כלן שלא יחטאו בהן כלל רק במשפטים יעמידו התורה כמו שנאמר בהן (להלן כא כא) וכל ישראל ישמעו ויראו ועוד כי רבים ירחמו מלסקול האיש ולשרוף אותו אחרי שנעשת העבירה כמו שנאמר (להלן יט יג) לא תחוס עינך ועוד שייראו מן התקיפים ומן המטעים כמו שאמר (לעיל א יז) לא תגורו מפני איש כי המשפט לאלהים הוא ואמר בנביא השקר (להלן יח כב) לא תגור ממנו והזכיר כל אלה במסית (להלן יג ט) לא תאבה לו ולא תשמע אליו ולא תחוס עינך עליו ולא תחמול ולא תכסה עליו ויזהיר לא תשמע אליו מפני הטעאתו ולא תחוס עינך מפני הרחמנות שירחמו רכי הלבב על הנידונים ולא תכסה שלא תשתוק בעבור תקפו ויראת בני משפחתו
@2 **וטעם ואהבך** . כאשר תעשה המשפטים לאהבת השם גם הוא יאהב אותך ויתכן שיהיה "ואהבך" יוצא שמחבב אותך למשפחות הנשפטים ולא ישנאוך עליהם וברכך שלא תאונה אליך רעה בעבור המשפט והרבך שלא תמעט באבדן העוברים אפילו יהיו רבים אובדים כאנשי עיר הנדחת
@4 **והסיר ה' ממך כל חולי** . הנהוג לבא בעולם והזכיר כל מדוי מצרים הרעים להבטיח ונתנם בכל שונאיך או שירמוז כי בעשותם המשפטים ינצלו מהם ואם לא יעשו אותם יבואו עליהם כאשר באו על המצרים כאמור בתוכחות (להלן כח ס) והשיב בך את כל מדוי מצרים וגו' וכבר פירשתי זה בסדר ויהי בשלח (שמות טו כו) והזכיר תחלה במשפטים לכלות ולהכרית עובדי ע"ז ולכך אמר ואכלת את כל העמים שתכריתם כענין שנאמר כי לחמנו הם (במדבר יד ט) כי אכל את יעקב (תהלים עט ז) ואכלוהו ויכלוהו (ירמיהו י כה) וכן רבים ואמר לא תחוס עינך עליהם כאשר הזכרתי (בפסוק יב) כי ברחמנות השופטים (ס"א הטפשים) יאבד כל משפט
@11 **לא תוכל כלתם מהר** . יבטיח שהשם יכריתם כלם וישלח בהם את הצרעה להאביד הנשארים והנסתרים והנה כלם יאבדו אבל אמר שלא יכלה אותם במלחמה ביום אחד ולא שיגרשם מן הארץ בשנה אחת פן תהיה הארץ שממה ורבה עליך חית השדה והוסיף עוד להבטיח שלא יהיו אלה הנשארים רובם אבל השם יהומם מהומה גדולה ורובם יאבדו ביד ישראל וכן אמר (להלן ט ג) הוא ישמידם והוא יכניעם לפניך והורשתם והאבדתם מהר שיאבדו רובם במהרה לא שיכלו עד אשר תפרה ונחלת את הארץ ואמר ונתן מלכיהם בידך והאבדת את שמם עד שלא יהיה להם שם על פני חוץ וכל הנצב בפניהם ישמידו וזה כענין שבא ביהושע (יא כ) כי מאת השם היתה לחזק את לבם לקראת המלחמה את ישראל למען החרימם ולא נשאר להם מלך בארץ כי כל מלכיהם נפלו וכתב רש"י פן תרבה עליך חית השדה והלא אם עושים רצונו אינם מתיראים מן החיה שנאמר (איוב ה כג) וחית השדה השלמה לך אלא גלוי היה לפניו שעתידין לחטוא ודברי רבותינו הם (ספרי) ואף על פי שהפרשה הזאת להבטחה נאמרה כבר הזכרתי (לעיל ד כה) כי משה רבינו במשנה התורה יבטיח ויזהיר וירמוז כי לא תגיע זכותם להכריתם כלם כאחד ושישבית חיה רעה מן הארץ כמובטח להם בפרשת אם בחקתי (ויקרא כו ו) אבל יהיה כאשר אמר שיאבידו את רובם ומלכיהם בתחלה ואחרי כן יאבדו הנשארים
@14 **לא תחמד כסף וזהב עליהם** . יחסר "אשר" לא תחמוד כסף וזהב אשר עליהם והוא נויי ע"ז צוה תחלה לשרוף ע"ז עצמה שהיא "פסילי אלהיהם" ואסר גם כן הנויין שעליהן והזהיר עוד ולא תביא תועבה אל ביתך והיית חרם כמהו לאסור בהנאה כל עניני ע"ז היא ומשמשיה ותקרובת שלה והנויין
@16 **וטעם כל המצוה** . לומר אע"פ שהזהרתי אתכם במשפטים גם כל המצות תשמרון לעשות כי בעשיית כלן תחיון ורביתם בפרי בטן ופרי בהמה ופרי האדמה ככל הנזכר למעלה
@17 **וזכרת את כל הדרך וגו'** . יאמר כי תוכל לדעת שיש בעשיית המצות טובה שלמה ולא יהיה צדיק נעזב ומבקש לחם כי השם מפרנס אותך במדבר במעשה נס גדול בעבור לכתך אחר מצותיו וכבר פירשתיו בפרשת המן (שמות טז ד) טעם למען ענותך לנסותך לדעת את אשר בלבבך התשמר מצותיו אם לא כי היה נסיון גדול להם שלא ידעו עצה לנפשם ויכנסו במדבר הגדול לא מקום לחם ואין בידם כלום מן המן אבל ירד דבר יום ביומו וחם השמש ונמס וירעבו אליו מאד וכל זה עשו לשמור מצות השם ללכת כאשר יצוה והשם היה יכול להוליכם בדרך הערים אשר סביבותיהם אבל הביאם בנסיון הזה כי ממנו יודע שישמרו מצותיו לעולם
@18 **וטעם אשר לא ידעת ולא ידעון אבתיך** . כי לא ידעת במן שתוכלו לחיות בו ימים רבים ולא הגיע אליכם כן בקבלה מאבותיכם או יאמר כי עשה עמכם החסד הגדול הזה אשר אבותיכם הקדושים לא הגיעו אליו כי אף על פי שהלכו אחריו ככל אשר צוה אותם לך לך מארצך וממולדתך ומבית אביך (בראשית יב א) לא הגיע מעלתם שיפרנסם בדגן שמים כאשר עשה לך וכן אמרו במדרש במדבר סיני רבה (א ב) בזכות משה הייתם אוכלים המן מה שלא ראו אבותיך הקדושים שנאמר ולא ידעון אבותיך ופירש כי עשה זה להודיעם כי הוא המחיה האדם בכל אשר יגזור א"כ שמור מצותיו וחיה ויתכן לפרש כי ויענך וירעיבך ויאכילך את המן ענינים שונים יאמר כי ענה אותך בלכתך במדבר ארבעים שנה כענין ענה בדרך כחי (תהלים קב כד) וירעיבך מתחלה כמו שאמרו (שמות טז ג) להמית את הקהל הזה ברעב ואחרי כן האכילך את המן להודיעך כי על כל מוצא פי ה' יחיה האדם וכן המאכילך מן במדבר אשר לא ידעון אבותיך (פסוק טז) וספר הנס שעשה להם ו"למען ענותך" שב אל המוליכך במדבר הגדול והנורא וגו' וצמאון וגו' (פסוק טו) אבל מה שאמר בפרשת המן (שמות טז ד) למען אנסנו הילך בתורתי אם לא שאתן לכם צרכיהם ושאלתם אביא להם ואראה אם ישמעו אלי ברבות הטובה וזה עולה בדרך הפשט אבל הענין הראשון הוא אמת ונכון
@19 **שמלתך לא בלתה מעליך** . ענני כבוד היו שפין בכסותן ומגהצים אותם כמו כלים המגוהצים וכן קטניהם כשהיו גדלין גדל לבושן עמהם לשון רש"י ודברי אגדה (מדרש תהלים כג) אבל ר"א כתב ואחרים אמרו כי הוציאו מלבושים רבים ויתכן שאין בתולדת המן להוליד זיעה וכן אמר ורגלך לא בצקה שנתן להם כח או הוליכם לאט ואין דבריו נכונים כי משה יזכיר להם זה לאמר כי בעשיית המצוה יהיה להם מזון וכסות ויחליפו כח כאשר חיו במן ארבעים שנה והיו להם השמלות וארח ברגלם לא יבא והכל ממעשה הנס כי על כל מוצא פי ה' יחיה האדם ויתפרנס ואם תכסה את הקורה בשמלה חדשה בארבעים שנה תבלה אע"פ שאין בה זיעה אף כי אנוש רמה
@20 **כי כאשר ייסר איש את בנו** . שיתן עליו לטובתו עול מוסר כענין שנאמר (משלי יט יח) יסר בנך כי יש תקוה ואל המיתו אל תשא נפשך כן ה' אלהיך מיסרך מתחלה בענוי המדבר ונסיון המן שתערב לנפשך טובת הארץ ופירותיה על כן אמר אחריו (פסוק ז) כי ה' אלהיך מביאך אל ארץ טובה
@22 **וטעם ארץ נחלי מים** . שהיא כגן רוה לא שישקוה מים ברגל כארץ מצרים כאשר יאמר עוד (להלן יא יא) כי למטר השמים תשתה מים ופירש כי עינות ותהומות יוצאים בבקעה וגם בהר ומשם יזחלו בה נחלים ושיעור הכתוב עינות ועינות תהומות כמו בעזוז עינות תהום (משלי ח כח) מעינות תהום רבה (בראשית ז יא) והענין כי יש מן המעינות שנוזלים מתמצית לחות ההרים מן הגשמים שנבלעים בתוכם או מן האדים העולים להם והם שקרא עיינות כמו אל כל מעיני מים (מלכים א יח ה) למעינו מים (תהלים קיד ח) ויש מהם שיוצאים ממקור התהום והם שקראם "תהומות" כלומר מעינות תהום ואמר כי משניהם בבקעה וגם בהר
@24 **וטעם אשר אבניה ברזל** . כי במקום אשר תחשוב ששם אבנים שם תמצא ברזל כי מעפרה יוקח ובשרם כי בארץ ישראל מחצב נחשת וברזל שהם צורך גדול ליושבי הארץ ולא תחסר כל בה אבל מוצא הכסף והזהב איננו חסרון בארץ ובתרגום ירושלמי ראיתי דאבנהא ברירן היך פרזלא וכו' ר"ל שהכתוב משבח הארץ שימצאו בה מחצבים מן אבנים גדולות אבנים יקרות אבני גזית לבנות מהם בתים וחומות ומגדלים לא כארץ מצרים וארצות רבות שהם שוכני בתי חומר ונעשים ליושביהם קבריהם
@25 **ואמר ואכלת ושבעת וברכת** . כי תזכור עבודת מצרים וענוי המדבר וכאשר תאכל ותשבע בארץ הטובה תברך עליה את השם ורבותינו (ברכות מח) קבלו שזו מצות עשה וטעמו ותברך את ה' אלהיך וכן ועשית מעקה לגגך (להלן כב ח) וכן ועשית פסח לה' אלהיך (להלן טז א) ולקחת מראשית כל פרי האדמה (להלן כו ב) ורבים כן וטעם על הארץ הטובה כמו ועל הארץ הטובה יצוה שתברכהו בכל עת שתשבע על השובע ועל הארץ שנתן לך שינחילנה לך לעולמים ותשבע מטובה והנה חיוב המצוה הזאת בכל מקום
@33 **וזכרת את ה' אלהיך כי הוא הנותן לך כח לעשות חיל** . ידוע כי ישראל גבורים ואנשי חיל למלחמה כי נמשלו לאריות ולזאב יטרף ומלכי כנען במלחמה נצחו אותם על כן אמר אם תחשוב כחי ועצם ידי עשה לי את החיל הזה תזכור השם שהוציא אותך ממצרים ולא היה לך שם כח ועצם יד כלל ותזכור עוד כי במדבר אשר אין לאל ידך לחיות שם עשה לך כל צרכך אם כן גם החיל הזה אשר עשית בכחך השם הוא שנתן לך הכח כאשר עשית אותו ואם תשכח את השם יכלה כחך ושארך ותאבד כאשר אבדו הם כי כל עוזבי ה' יכלו וחזר להביא עוד ראיה אחרת שלא תחשוב כחי ועצם ידי וגו' ואמר (ט א) שמע ישראל דבר אמת מפי כי הגוים האלה הם גדולים ועצומים ממך ואיך תנצחם במלחמה ועוד יש להם ערים גדולות ובצורות לרום השמים ואיך תכבוש אותם ועוד ששם עם גדול ורם בני ענקים שאתה ידעת מן המרגלים שראו אותם ואתה שמעת מימים ראשונים שלא יתיצב אדם לפניהם וכשיתברר לך כל זה יש לך לדעת ולהאמין מן היום הזה כי לא תוכל לעבור עליהם כלל עד שתדע בלבבך כי ה' העובר לפניך הוא אש אוכלה והוא ישמידם ויכניעם לא כח ועצם יד שנתן לך אבל יד ה' עשתה זאת בתקיפין שבהם וזה רמז למה שאמר (יהושע י יא) וה' השליך עליהם אבנים גדולות מן השמים וכן אמר שם (פסוק יד) ולא היה כיום ההוא לפניו ואחריו וגו' כי ה' נלחם לישראל והערים הבצורות שהזכיר כאן רמז לחומת יריחו שנפלה לפני הארון וזהו שאמר דוד (תהלים מד ד) כי לא בחרבם ירשו ארץ וזרועם לא הושיעה למו כי ימינך וזרועך ואור פניך כי רציתם ימין השם וזרועו בתקיפים ואור פניו שרצם בהרוגי המלחמה שנתן להם כח עליהם וזהו שאמר הכתוב עוד (עמוס ב ט) ואנכי השמדתי את האמורי מפניהם אשר כגובה ארזים גבהו וחסון הוא כאלונים ואשמיד פריו ממעל ושרשיו מתחת ייחד האמורי שהיה עצום בהם והשם הוא המשמיד אותו
@38 **וטעם הוא ישמידם והוא יכניעם** . כמו הוא יכניעם והוא ישמידם "יכניעם" ענין שפלות מן הראית כי נכנע אחאב מלפני (מלכים א כא כט) או אז יכנע לבבם הערל (ויקרא כו מא) וכן כלם והטעם כי היו העמים ההם יראים מאד מישראל ובלב רגז וברוח שפלה ורפיון ידים היו יוצאים אליהם למלחמה כמו שאמר (יהושע ה א) ויהי כשמוע כל מלכי האמרי וגו' וכל מלכי הכנעני וגו' וימס לבבם ולא היה בם עוד רוח מפני בני ישראל ויתכן כי "הוא ישמידם" ירמוז אל גוים גדולים ועצומים ו"יכניעם" אל בני ענקים כי עם כל תקפם וגבהם נכנע לבם יותר משאר העם ולא יצאו למלחמה כלל אבל היו נחבאים בהרים ובערי הבצורות כמו שאמר (שם יא כא) ויבא יהושע בעת ההיא ויכרת את הענקים מן ההר מן חברון מן דביר מן ענב ומכל הר יהודה ומכל הר ישראל עם עריהם החרימם יהושע כלומר בעריהם וכן וילך יהודה אל הכנעני היושב בחברון ויכו את ששי ואת אחימן ואת תלמי (שופטים א י)
@39 **אל תאמר בלבבך** . אחרי שהזהיר שלא תחשוב כחי ועוצם ידי עשה לי רק שתדע כי הנצוחים במלחמה השם נתן להם הכח ההוא והתקיפים שבהם והערים הבצורות אשר תלכדו השם בכבודו עשה לכם כן בנס מפורסם מאתו חזר והזכיר לא תחשוב כי עשה ה' עמך כל זה בצדקתך כי לא עשה לכם כן רק ברשעת הגוים האלה והנה זה טעם באבדן הגוים ההם ולא נתן להם טעם ברשת ישראל את הארץ על כן חזר ובאר לא בצדקתך שתהיה צדיק במעשה ולא אפילו בלב ישר שהיה לך רק ברשעת הגוים אבדו הם ובעבור שבועת אבותיך ירשת אותה הארץ כי אין החטא שלך יכול לבטל המתנה שנתן לאבותיך כי בשבועה נתנה להם ורש"י כתב אל תאמר בלבבך צדקתי ורשעת הגוים גרמה לי לא בצדקתך ואיננו נכון ויש על השואל לשאול שהרי אמר (לעיל ז ח) כי מאהבת ה' אתכם והנה הם אהובים למעלה והשם לא יאהב רק את הטובים כי רשע ואוהב חמס שנאה נפשו אם כן גם בצדקתם ירשו ארץ והתשובה כי שם ידבר עם ישראל בכללם וכאן יוכיח הדור ההוא שהיו ממרים את ה' מיום היותם במדבר וטעם ולמען הקים את הדבר שאמר ועבדום וענו אותם ארבע מאות שנה ודור רביעי ישובו הנה (בראשית טו טז)
@43 **ובחרב הקצפתם את ה'** . קודם שיפתח להם בביאור התורה כלל הוכיח אותם בעונות אשר גרמו להם רעה ולא נמחלו והזכיר להם ענין המרגלים ומי מריבה ואחר כן ביאר עשרת הדברות ופרשת יחוד השם והזהירם בענין ע"ז אזהרות רבות והזהיר במצות בכללם ויאמר שהן כולן טובות ובעבורן תבא להן כל הטובה ועתה בא להתחיל בפרטי המצות וקודם שיזכיר אחת מהן בפרט יחזור להוכיח אותם ולפקוד עליהם את כל עונותיהם שעשו מעת שקבלו התורה והלאה כי התלונות שעשו קודם מתן תורה שהמרו על ים בים סוף וילונו במרה ובאלוש לא יזכירם להם כי מעת שקבלו התורה היו יותר חייבים לשמוע בקול השם אשר כרת עמם ברית ולפיכך פתח כאן ובחורב הקצפתם והזכיר להם מעשה העגל וכבר פירשתיו (שמות לב א)
@50 **ואפן וארד מן ההר** . כבר פירשתי במקומו (שם שם יא) כי קודם שירד מן ההר התפלל עליהם ובתפלתו נאמר (שם שם יד) וינחם ה' על הרעה אבל לא הזכיר זה עתה מפני שהוא רוצה להסדיר להם עתה הטורח הגדול והעמל שטרח עליהם כי הביאו אותו לשבור הלוחות ולהתנפל עליהם ארבעים יום וארבעים לילה ולהתפלל גם על אהרן כי התאנף השם עליו מאד ואחרי כן (פסוקים כה-כט) יזכיר התפלה הראשונה שחלה את פני ה' אלהיו טרם רדתו שלא ישמידם
@52 **וטעם ואתפש בשני הלוחות** . גם זה מן התוכחות יאמר היה עונכם גדול מנשוא עד כי בראותי אתכם משחקים לפני העגל לא יכלתי להתאפק ושברתי הלוחות והוצרך להזכיר זה בעבור שירצה להודיעם ענין הלוחות השניות כאשר יפרש ויתכן שירמוז עוד לטובה שעשה עמהם כי סכן בנפשו לשבור לוחות האלהים לטובתם כאשר אמרו רבותינו (שמו"ר מג א) מוטב תדון בפנויה ולא באשת איש
@54 **כי יגרתי מפני האף** . יאמר כי מפני האף והחמה אשר קצף השם מתחלה עליכם להשמיד אתכם יגורתי גם עתה כי עדין יש עליכם להשמיד אתכם מן הקצף הגדול ההוא אף על פי שכבר נחם השם על הרעה אשר דבר לעשות לעמו על כן חזרתי והתנפלתי עליכם ארבעים יום וארבעים לילה עד ששמע אלי גם בפעם ההיא כאשר שמע בפעם הראשונה קודם שירדתי וגם בעד אהרן התפללתי בפעם הזאת שחזרתי שם כי עד שיבער את העגל לא השגיח רק להשיב חמתו מהשחית את העם כרגע
@56 **ואמר ואשלך את עפרו אל הנחל הירד מן ההר** . ולא הזכיר כי השקהו אותם דרך כבודם שלא רצה לאמר להם שעשה בהם מעשה הסוטות
@57 **ובתבערה ובמסה** . בעבור כי בתבערה היו העם כמתאוננים מנסים השם בתואנות הזכיר להם כי הייתם מקציפים את השם בנסיון אשר נסיתם בתבערה כאשר עשיתם כבר פעם אחרת במסה ולא לקחתם מוסר ויפה פירש והנה החטא לנסות את השם הוא חטא גדול ואשמה רבה כאשר הזהיר ממנו (לעיל ו טז) לא תנסו את ה' אלהיכם כאשר נסיתם במסה על כן החזיר אותו להם בכאן וכך הזכיר פעם אחרת חטא המרגלים בקצרה בעבור העון הגדול כי בו ישלים ממרים הייתם עם ה' ואמר מיום דעתי אתכם לרמוז על תלונותיהם קודם מתן תורה
@60 **ואתנפל לפני ה'** . יאמר כי הוצרכתי להתנפל עליכם ארבעים יום וארבעים לילה על החטא הגדול הזה כי מתחלה אמר ה' להשמיד אתכם עד שאתפלל אל ה' ואומר אל תשחת עמך ונחלתך כי זאת היתה תפלתו קודם רדתו מן ההר וממנה נענה בוינחם ה' על הרעה אשר דבר לעשות לעמו (שמות לב יד) ולא הזכיר תפלת הארבעים יום וארבעים לילה כי ארוכה מארץ מדה ורחבה מני ים וטעם השמות הכתובים באל"ף דל"ת יו"ד ה"א פרשתיו (לעיל ג כד)
@63 **מבלי יכלת ה' להביאם אל הארץ אשר דבר להם** . אמר במרגלים (במדבר יד טז) מבלתי יכולת ה' להביא את העם הזה אל הארץ אשר נשבע להם וישחטם במדבר כלומר יאמרו כי כאשר באו והיו קרובים לארץ וראה שאין יכולת בידו כנגד העמים ההם שחטם במדבר אבל בכאן אמר ומשנאתו אותם הוציאם להמיתם במדבר כי היתה השנאה הזאת בהם במצרים טרם שהוציאם משם והטעם בעבור שהיו במעשה העגל עדין קרובים למצרים רחוקים מארץ כנען יאמרו כי גם בהיותם במצרים ראה שאין יכולת בידו להביאם אל הארץ אשר דבר להם באזני המצריים ועל כן שנאם ו לבלתי החל לעיני הגוים אשר נודע אליהם לעיניהם (ו) הוציאם ממצרים להמיתם במדבר במקום שלא יודע מה היה להם וזהו ברעה הוציאם להרג אותם בהרים (שמות לב יב) שחשב עליהם מחשבת רעה טרם שיצאו שהוציאם מתוך עם מצרים להרוג אותם בין ההרים מקום אשר לא יעבור בו איש ולא ישב אדם שם והכונה בטענות כי הגוים ידברו בה' אלהי ישראל לאמר עליו כאלהי גויי הארצות וכענין שנאמר (דניאל י כ) ועתה אשוב להלחם עם שר פרס וכבר הזכרתי מן הענין הזה
@65 **בעת ההיא אמר ה' אלי פסל לך** . אחר שהתנפלתי לפני ה' את ארבעים היום ואת ארבעים הלילה נתרצה אלי שיכתוב לוחות שניות אבל היו הראשונות מעשה אלהים והמכתב מכתב אלהים ובאלו צוה אותי שיהיו מחצב ידי והמכתב יהיה כמכתב הראשון באצבע אלהים וטעם ועשית לך ארון עץ שתשים הלוחות בתוכו בעת שתרד והיה הארון הזה כולו עץ הוא והמכסה אשר עליו מלמעלה כמנהג בכל הארונות והיו הלוחות שם עד שנעשה המשכן ואז עשו הארון המצופה זהב והכפורת אשר עליו זהב טהור ולא אמר לו כן בלוחות הראשונות לפי שהיה גלוי לפניו שישברם וטעם ויהיו שם כאשר צוני ה' (פסוק ה) שהיו שם עד שנעשה המשכן שצוני (שמות כה כא) ונתת את הכפורת על הארון מלמעלה ואל הארון תתן את העדות אשר אתן אליך וזהו הטוב והישר בפסוקים האלה וכתב רש"י ולא זהו ארון שעשה בצלאל שהרי לא נתעסקו במשכן אלא לאחר יום הכפורים כי ברדתו מן ההר צוה להם על מלאכת המשכן ובצלאל עשה המשכן ואח"כ ארון וכלים נמצא זה אחר היה וזהו שהיה יוצא עמהם למלחמה ואותו שעשה בצלאל לא יצא במלחמה אלא בימי עלי ונענשו עליו ונשבה זה לשון הרב ודברי אגדה הם שמצא כתוב בתנחומא ויש לשאול ואחר שהוציא משם הלוחות ונתנם בארון שעשה בצלאל מה היה בזה ולמה הוא יוצא עמהם למלחמה ואומרים ששברי הלוחות היו שם וכן באגדה אבל דברי יחיד הם שכך שנינו במסכת שקלים (ירושלמי פ"ו ה"א) תניא רבי יהודה ברבי אלעאי אומר שני ארונות היו עם ישראל במדבר אחד שהיו שברי הלוחות מונחין בו וכו' ורבנן אמרי אחד היה ופעם אחת יצא בימי עלי ונשבה ודעת רבותינו בכל מקום בתלמוד (ברכות ח ב"ב יד מנחות צט) אינו כן אלא לוחות ושברי לוחות מונחים בארון ועוד אנה יעמוד הארון הזה עם הלוחות הראשונות כל ימי המדבר כי במשכן בבית קדשי הקדשים לאחר הפרוכת אין שם שני ארונות וכן שלמה לא הכניס לבית קדשי הקדשים אלא ארון אחד (מלכים א ח ו-ט)אבל הארון הזה של משה כשנעשה ארונו של בצלאל גנזוהו כדין תשמישי קדושה וזהו הנכון על דעת רבותינו כי על דרך הפשט יתכן כי ועשית לך ארון עץ ירמוז לארון שעשה בצלאל וזה כי מתחלה נצטווה משה על המשכן וכליו והיתה המצוה הראשונה ועשו ארון עצי שטים (שמות כה י) כי היא עיקר הכוונה בכל המשכן להיות השם יושב הכרובים ואחרי כן עשו את העגל וכאשר נתרצה השם למשה ואמר לו שיכתוב על הלוחות האלו כמכתב הראשון צוהו בקצרה שיעשה ללוחות האלה ארון עץ היא המצוה לו ללוחות הראשונות והנה הזכיר לו המצוה הראשונה שבענין המשכן ושהכל תלוי בה ומזה למד משה לעשות המשכן וכליו כאשר נצטווה מתחלה ויהיה פירוש ויהיו שם כאשר צוני ה' שהיו שם לעד לעולם כאשר צוהו ה' מתחלה (שם שם כא-כב) ואל הארון תתן את העדות אשר אתן אליך ונועדתי לך שם ודברתי אתך וגו' והנה ברדתו הניח הלוחות באהל מועד עד שיעשה הארון והמשכן כי אלו לא שבר הלוחות הראשונות באהל מועד יהיו עד עשות בצלאל הארון וכן שברי הלוחות על כרחנו שם היו כי לא החזירם עמו להר וראיה לזה שלא הזכיר משה זו הצואה בסדר כי תשא כי שם הזכיר ארון בצלאל בפירוש וכאן לא הזכיר המשכן וכליו כי הם הרואים אותו ולפיכך הזכיר זה בקצרה ואל יקשה בעיניך שאמר ואעש ארון עצי שטים ואפסל שני לוחות אבנים כי השלים ענין הארון כאחד כי הנה צוהו השם פסל לך וגו' ועלה אלי ההרה ועשית לך ארון עץ שיעלה תחלה בלוחות ואחרי כן יעשה ארון עץ אבל האריך לומר ואכתב על הלוחות את הדברים אשר היו על הלוחות הראשונים אשר שברת ושמתם בארון לומר שיהיו כראשונות במכתב וראוי שיהיו בארון המצוה כראשונות שאועד שמה לבני ישראל ונקדש בכבודי ולכך השלים ואעש ארון להשלים המצוה והמעשה בקצרה ואחרי כן שב להאריך במוקדם וטעם ואפן וארד מן ההר ואשם את הלוחות בארון אשר עשיתי שעשיתיו ברדתי ויהיו שם לעד כאשר צוני ה' להיות כבודו שוכן בתוך בני ישראל
@70 **ובני ישראל נסעו מבארות בני יעקן מוסרה** . מה ענין זה לכאן? ועוד וכי מבארות בני יעקן נסעו למוסרה והלא ממוסרה באו לבני יעקן שנאמר (במדבר לג לא) "ויסעו ממוסרות ויחנו בבני יעקן"? ועוד "שם מת אהרן" והלא בהר ההר מת? צא וחשוב ותמצא שמונה מסעות ממוסרות להר ההר? אלא אף זו מן התוכחות: ועוד זאת עשיתם כשמת אהרן בהר ההר בסוף ארבעים שנה ונסתלקו ענני הכבוד יראתם לכם ממלחמת מלך ערד ונתתם ראש לחזור למצרים וחזרתם לאחוריכם שמונה מסעות עד בני יעקן ומשם למוסרה, שם נלחמו בכם בני לוי והרגו מכם ואתם מהם עד שהחזירו אתכם לדרך, ומשם חזרתם הגדגדה הוא חור הגדגד, ומן הגדגד למוסרה, ובמוסרה עשיתם אבל גדול על מיתתו של אהרן שגרמה לכם זאת ונדמה לכם כאלו הוא מת שם. וסמך משה תוכחה זו לשבירת הלוחות לומר שקשה מיתתן של צדיקים לפני הקדוש ברוך הוא כיום שנשתברו הלוחות, ולהודיעך שקשה לו מה שאמרו "נתנה ראש" לפרוש ממנו כיום שעשו את העגל. בעת ההיא הבדיל ה' את שבט הלוי מוסב לענין הראשון בעת ההיא בשנה הראשונה שיצאתם ממצרים וטעיתם בעגל ובני לוי לא טעו הבדילם המקום מכם. וסמך זה לחזרת בני יעקן לומר שאף בזה לא טעו בה בני לוי אלא עמדו באמונתם כל זה לשון רבינו שלמה מדברי אגדה (ירושלמי יומא פ"א ה"א).
@70 והוצרך רבי אברהם לומר בדרך הפשט כי בארות בני יעקן איננו בני יעקן, ומוסרה איננו מוסרות, אבל קדש נקרא בארות בני יעקן ושם (ב) מדבר הר ההר מוסרה משם נסעו הגדגדה איננו חר הגדגד רק הוא שם כלל לצלמונה ופונון ואובות ויטבתה הוא המקום הנקרא בארה (במדבר כא טז), וזה טעם ארץ נחלי מים, וידבק "ומן הגדגדה יטבתה" עם "ויכהן אלעזר" כי שם ביטבתה כהן אלעזר בכהונה גדולה והקריב קרבנות.
@70 וכל אלה דברי רוח כי איך יתכן שכל המקומות האלה הרבים שיהיו כולם מקומות חדשים שלא נזכרו במסעות?
@70 ועוד: שמנהג הכתוב בכל מקום לשנות מעט בהזכירו השמות פעמים בין בשם מקום בין בשם אדם, וכל שכן בכאן שהם שוים כי מוסרה ומוסרות איננו שנוי והפרש וכן חר הגדגד והגדגדה שם אחד ויטבתה שוה לגמרי?
@70 ועוד: כי בהר ההר כהן אלעזר כשמת אביו כאשר הלבישו הבגדים, כי מיד היה מרובה בבגדים, וזה משפט הכהנים הגדולים אפילו לדורות?
@70 והנראה בעיני כי הר ההר, גדול שבהרים וארוך פרסאות רבות, ושמו מוכיח כי הוא יקרא "הר", ויאמרו לו "ההר" לגודלו וארכו. וכך אמרו רבותינו (במדב"ר יט טז) שהיה הר על גבי הר והיה סוף ההר עד גבול ארץ אדום וראשו קרוב לחשמונה, והיו במישור אשר לפני הר ההר ערים או מקומות הנקראים מוסרות ובני יעקן וחור הגדגד ויטבתה ועברונה ועציון גבר וקדש, ואלו המקומות אין ביניהם מרחק רב כי המחנה הגדול ההוא ביום אחד מהלכים כמו פרסה או פחות מכאן, ונסעו מקדש ויחנו בהר ההר שנכנסו בו במקום שפל אשר היה ברגלי ההר, ואז צוה ה' למשה (במדבר כ כה) "והעל אותם הר ההר" שיעלה למעלה אל ראשו הוא תחלת ההר והנה עלו אל ראשו של הר והגיעו כנגד מוסרות ומת אהרן שם, והוא שנאמר (שם פסוק כח) "וימת אהרן שם בראש ההר" והנה מיתתו במוסרה? ואפשר שהיו המקומות האלה בשמם נחשבים בהר עצמו ויקרא ראש ההר וכנגדו במישור מוסרות, ושם כל אחד מוסרה שיאמרו מוסרה אשר בהר ומוסרה אשר בשפלה. והיו במקום הנקרא חשמונה בארות בשדה, יקראו אותן בארות בני יעקן כי אנשי בני יעקן באים שם להשקות צאנם, והם עשאום כי שם מצאו מים חיים, ומשם נסעו למוסרה ומשם נסעו למוסרות ויסעו ממוסרות ויחנו בבני יעקן שהמקום ההוא זה שמו. וספר הכתוב "משם נסעו הגדגדה, ומן הגדגדה יטבתה ארץ נחלי מים" להודיע שעמדו שם ימים בעבור הנחלים, וקצר במסעיהם שכבר באר אותם אבל אמר כי משם ממוסרה נסעו אל הגדגדה ואל יטבתה שהיא כולה ארץ נחלי מים, כי מן גדגד ועד יטבתה כולה משקה. ויתכן עוד שנאמר כי כאשר עלה אהרן אל ראש ההר וימת בראש ההר כנגד מוסרות או במוסרה עצמה ויקבר שם חזרו ישראל אל מוסרות לבכות ולספוד על קבר איש האלהים, והיו גדוליהם בכל השלשים יום עולים אל ראש ההר וסופדים לקדוש ה', וישובו אל המחנה במוסרה. ואחר השלשים יום נסעו ממוסרה אל חר הגדגד ומן הגדגדה יטבתה כי עתה בשובם הלכו מהרה. וזה דבר נכון מאד בישוב המקראות על אופנן והזכיר כי היה שם המקום יטבתה בעבור שהיה מקום טוב כי שם נחלי מים ושאר המדבר ארץ ציה וצמאון אשר אין שם מים. וטעם הזכירו מיתת אהרן עתה במקום הזה כי אמר (לעיל ט כ) "וָאֶתְפַּלֵּל גַּם בְּעַד אַהֲרֹן בָּעֵת הַהִוא" ולא הגיעו עונש השמד לא בגופו ולא בזרעו כי לא מת עד שנת הארבעים שהיה זקן ושבע ימים וכהן בנו תחתיו. ואמר ובני ישראל נסעו ולא אמר "ואתם" כדרך כל הפרשה, כי בתוכחות ידבר עמהם להוכיח אותם אבל בזה יספר במסעי בני ישראל.
@72 **בעת ההיא הבדיל ה' את שבט הלוי** . מוסב לענין ראשון בעת ההיא בשנה הראשונה שיצאתם ממצרים וטעיתם בעגל ובני לוי לא טעו הבדילם המקום מכם לשון רש"י ואם כן יאמר כי מן העת ההיא הובדלו לפניו יתברך כי לא הבדילם במעשה עד השנה השנית בחדש השני או ירמוז למה שאמר להם (שמות לב כט) מלאו ידכם היום לה' כי יהיה זה לכם מלוא ידים בעבודת כהונה ולויה והנכון בעיני כי "בעת ההיא" השני כראשון (לעיל פסוק א) כי בעת שאמר לו פסל לך שני לוחות אבנים (שמות לד א) נתרצה לישראל ונצטוה על המשכן ואז נתרצה גם לאהרן ונצטוה (שם כח ד) ועשו בגדי קדש לאהרן אחיך ולבניו לקדשו לכהנו לי וצוהו במלואים ולכך אמר כי אלעזר כהן תחת אביו שהיתה בהם משחתם לכהונת עולם לדורותם ועשה הבדלת כל השבט ענין אחד כי מן היום ההוא היה לפניו שיהיו שבטו נתונים נתונים לו לעבוד עבודת המשכן או יאמר כי שבט הלוי נבדל בעת ההיא להיות הכהנים מהם כי גם הם נושאים הארון וכן ויתנה אל הכהנים בני לוי הנושאים את ארון ברית ה' (להלן לא ט) והם שישרתו לשם ויברכו בשמו וטעם עד היום הזה בעבור כהונת אלעזר כאומר אז הבדילם לשרתו ויהי כן עד היום הזה
@73 **וטעם על כן לא היה ללוי** . הוא בעבור שכולם משרתים ועוזרים את הכהנים בעבודתם כי כל דבר המקדש בעבור הקרבנות וכן אמר (במדבר יח ב) וגם את אחיך מטה לוי שבט אביך הקרב אתך וילוו עליך וישרתוך
@74 **ואנכי עמדתי בהר** . על דעת רבותינו (סדר עולם ו) יאמר שעמד בהר כשעלה שם ושני הלוחות בידו כימים הראשונים של לוחות הראשונות ארבעים יום וארבעים לילה וישמע ה' אלי גם בפעם השלישית כי עבר ה' על פניו ויקרא ה' ה' אל רחום וגו' (שמות לד ו) ובקש ממנו (שם שם ט) וסלחת לעוננו ולחטאתנו ונחלתנו ונענה ואמר קום לך למסע לפני העם ויבאו ויירשו את הארץ וזהו וראה כל העם אשר אתה בקרבו את מעשה ה' כי נורא הוא אשר אני עושה עמך (שם שם י) וטעם לא אבה ה' השחיתך שלא רצה שלא תבאו ותירשו את הארץ כטעם ויסף עוד להניחו במדבר ושחתם לכל העם הזה (במדבר לב טו) ועל דרך האמת לא רצה שתהיה משחת ממנו שלא יהיה שמו הגדול עמך וכבר רמזתי זה הענין בסדר כי תשא
@76 **מה ה' אלהיך שואל מעמך** . נמשך אל לטוב לך יאמר איננו שואל מעמך דבר שיהיה לצרכו אלא לצורכך כטעם אם צדקת מה תתן לו (איוב לה ז) רק הכל הוא לטוב לך ואמר הטעם כי לה' אלהיך השמים ושמי השמים הארץ וכל אשר בה וכולם נותנים כבוד לשמו איננו צריך לך רק באבותיך חשק ויבחר בזרעם אחריהם מכל העמים בכם שאתם מבחר זרעם ולא בישמעאל ולא בעשו וטעם כיום הזה כי כן יהיה בכל זרעם לעולם וכבר פירשתי (לעיל ז ז) החשק והבחירה ופירוש שמי השמים גלגלי ארבעה יסודות שהם בכח השמים למטה מהם כענין הארץ וכל אשר עליה (נחמיה ט ו) וכן אמר במזמור הללו את ה' מן השמים הללוהו במרומים (תהלים קמח) והזכיר מלאכיו וצבאיו ושמש וירח וכוכבי אור ואחר כך הללוהו שמי השמים
@80 **ומלתם את ערלת לבבכם** . שיהיה לבבכם פתוח לדעת האמת לא כאשר עשיתם עד היום שלא נתן ה' לכם לב לדעת ועינים לראות ואזנים לשמוע וערפכם לא תקשו עוד שלא תהיו כאבותיכם דור סורר ומורה שישבו עם המצרים וילמדו מעשיהם והם קשים לעזוב דרכם כמו שעשו את העגל וקראם שם (שמות לב ט) עם קשי ערף שלא ישובו מן הטעות שנכנס בלבם לחשוב שיש תועלת בעבודת המלאכים או צבא השמים אבל אתם תדעו ותשכילו ותאמינו כי ה' אלהיכם הוא אלהי האלהים ואדוני האדונים אלהי האלהים הם מלאכי מעלה ואדוני האדונים כל צבא השמים אשר להם ממשלה בשפלים כי הוא האדון אשר שם להם משטרם בארץ ולו הגדולה והגבורה והוא נורא בתפארת עוזו אשר לא ישא פנים לאחד מן האלהים והאדונים להגן על עובדיהם ולא יקח שחד מיד אדם ופירשו בשחד שאפילו חסיד גמור שיעבור עבירה לא יקח ממנו מצוה ממצותיו בשחד לכפר לו אבל יענישהו על חטאיו ויגמול לו ככל טובותיו ואונקלוס תרגם דלית קדמוהי מסב אפין ואף לא לקבלא שוחדא יתכוין לפרש שהוא משבחי השלילות בבורא יתברך יאמר הכתוב שאין השם בענין שישא פנים כי לא יראנו האדם וחי והכל כאין נגדו ומאפס ותהו נחשבו לו ולא בענין שיקח שוחד וממון מאדם כמלכים ושופטי הארץ והנכון בעיני שיאמר אשר לא ישא פנים לגדולי בני אדם בריבם עם קטניהם ולא יקח שוחד מעשיריהם בריבם עם דל כי הוא עושה משפט יתום ואלמנה מן הגדולים וקבע את קובעיהם נפש ואוהב גר לתת לו לחם ושמלה והם כל צרכי האדם והנה הוא יפרנס העניים אשר אין להם אוהב ורע
@83 **כי גרים הייתם בארץ מצרים** . מום שבך אל תאמר לחברך לשון רש"י וכבר פירשתי בסדר ואלה המשפטים (שמות כב כ)
@85 **וטעם הוא תהלתך והוא אלהיך** . הוא יהיה תהלתך שתתן כל תהלתך אליו אותו תהלל תמיד וכבודו לאחר לא תתן ותהלתו לפסילים ולא אל האלהים והאדונים הנזכרים או יאמר הוא תהלתך שבו אתה מהולל על כל העמים כלשון כי תפארת עזמו אתה (תהלים פט יח) ה' עזי ומעזי (ירמיהו טז יט)
@85 "והוא אלהיך" - שיחד שמו עליך שתהיה לו לעם והוא יהיה לך לאלהים ולא כשאר האומות אשר הוא להם אלהי האלהים אשר חלק להם כמו שפירשתי (ויקרא יח כה) כי עשה עמך הגדולות והנוראות שמהם תכיר כי אתה חבלו ונחלתו ועיניו תמיד עליך לטוב
@87 **ושמרת משמרתו** . ליראה אותו שתשמור מחטוא לפניו כי אחר שיצוה באהבה יצוה ביראה ויצוה בחוקים ובמשפטים ובמצות או ושמרת משמרתו שתשמור מה שהשם שומר שהוא שומר את הגרים וחונן דלים ואביונים ועושה משפט יתום ואלמנה וכענין שנאמר במקום אחר (מלכים א ב ג) לשמור את משמרת ה' אלהיך ללכת בדרכיו ואמרו (שבת קלג) מה הוא חנון ורחום אף אתה היה חנון ורחום וכו'
@88 **את גדלו את ידו החזקה וזרועו הנטויה** . אמר ר"א להוציא אתכם ממצרים והאותות והמופתים שעשה לפרעה ואשר עשה לכם במדבר בדבר המן ואיננו נכון בעיני כי עתה לא ידבר רק במוסר אשר ייסר בו השם לעוברי רצונו את גדלו שהיה מתרומם ומתגדל לאמר התפאר עלי (שמות ח ה) למחר יהיה (שם פסוק יט) ושמתי פדות (שם) למען תדע כי לה' הארץ (שם ט כט) ואת ידו החזקה ושלחתי את ידי והכיתי את מצרים (שם ג כ) את היד הגדולה אשר עשה ה' (שם יד לא) וזרועו הנטויה שלא נתן להם ריוח והצלה מאז היתה ידו נטויה עליהם ולא השיב ידו מבלע עד שאבדם ואשר עשה לכם במדבר (פסוק ה) אשר נגף אתכם בעגל ואש תבערה והנחשים השרפים וקברות התאוה ומגפת השטים וגזרת המרגלים שהיתה בהם יד ה' עד בואם אל המקום הזה וקצר בפורענות שעשה להם ואם כן ושמרתם את כל המצוה למען תחזקו כי ידו החזקה מחזקת שומרי מצותיו ולא יחזיק ביד מרעים
@90 **אשר הציף את מי ים סוף וגו' ויאבדם ה' עד היום הזה** . לא הבינותי טעם "עד היום הזה" כי כל המתים בים אבדן עולם הם אובדים ויתכן שהוא חוזר לסוסיו ולרכבו שאבד סוס ורכב ממצרים בכל הדור ההוא כי כל סוס ורכב וכל פרש אשר במצרים הוציא עמו ואבדו כולם והיתה ממלכה שפלה בלא רכב וסוס וחיל ועזוז ואמר ר"א שלא קמו עוד בניהם תחתם להיות כמוהם ר"ל כי השם אבד הרודפים בים ואבד במצרים זרעם ולא נשאר להם שם ושאר כי הם הרשיעו יותר מכל מצרים לרדוף אחרי גאולי השם אבל זה לא נזכר בתורה
@92 **ואשר עשה לדתן ולאבירם** . ולא הזכיר קרח ועדתו שיצאה אש מלפני ה' ותאכל אותם בעבור כי איש זר הקרב להקטיר קטורת הוא מלאוי התורה (במדבר יז ה) ולעולם הוא נענש לדורות כאשר קרה גם לעזיהו (דהי"ב כו יט) על כן לא מנאו באותות המדבר
@96 **לא כארץ מצרים היא** . אלא טובה הימנה ונאמרה הבטחה זו לישראל ביציאתם ממצרים שהיו אומרים שמא לא נבוא אל ארץ טובה ויפה כזאת יכול בגנותה הכתוב מדבר וכך אמר להם לא כארץ מצרים היא אלא רעה הימנה תלמוד לומר וחברון שבע שנים נבנתה (במדבר יג כב) אדם אחד בנאן דרך ארץ אדם בונה את הנאה ואחר כך את הגרוע וכו' לשון רש"י מספרי (עקב יא) ועוד הביא מה שדרשו בגמרא במסכת כתובות (קיב) בענין אחר אפשר אדם בונה בית לבנו קטן ואחר כך לבנו גדול אלא שמבונה אחד משבעה בצוען ופשוטו של מקרא בדרך האזהרות נאמר שאמר להם ושמרתם את כל המצוה וירשתם ארץ זבת חלב ודבש כי ה' יתן מטר ארצכם בעתו והארץ תתן יבולה אבל דעו לכם שאינה כארץ מצרים להשקות אותה ברגל מן היאורים ומן האגמים כגן הירק רק היא ארץ הרים ובקעות למטר השמים תשתה מים לא בענין אחר וצריכה שידרוש ה' אותה תמיד במטר כי היא ארץ צמאה מאד וצריכה מטר כל השנה ואם תעברו על רצון ה' ולא ידרוש אותה בגשמי רצון הנה היא רעה מאד לא תזרע ולא תצמיח ולא יעלה בה כל עשב בהריה ויחזור ויפרש כל זה בפרשה השניה (להלן פסוקים יג-יז) כי אם שמוע תשמעו אל מצותי ונתתי מטר ארצכם בעתו יורה ומלקוש תמיד ואם לא תשמעו ועצר את השמים וגו' ואבדתם מהרה ברעב מעל הארץ הטובה שלא תוכלו לחיות בה בלא מטר והנה הפרשה הזו תזהיר במנהגו של עולם וממנה נלמד כי אע"פ שהכל ברשותו ונקל בעיני ה' יתברך להאביד יושבי ארץ מצרים ולהוביש נהרותם ויאוריהם אבל ארץ כנען תאבד יותר מהרה שלא יתן בה מטרות עוזו החולה צריך זכות ותפלה שירפאהו השם יותר מן הבריא שלא בא עליו החולי וכך המדה בעני ובעשיר ומאיר עיני שניהם ה' ומפני שאמר (פסוק יב) ארץ אשר ה' אלהיך דורש אותה וראוי שיאמר ולמטר השמים תשתה מים כאשר ה' אלהיך ידרוש אותה יהיה מדרש רבותינו (ספרי עקב יב) נרמז בכתוב והלא כל הארצות הוא דורש שנאמר (איוב לח כו) להמטיר על ארץ לא איש כביכול אינו דורש אלא אותה ועל ידי אותה דרישה שדורש אותה דורש כל הארצות תמיד עיני ה' אלהיך בה לראות מה היא צריכה ולחדש בה גזרות עתים לטובה ועתים לרעה כו' כדאיתא במסכת ר"ה (יז) ויש בו סוד עמוק כי הארץ הזאת נדרשת בכל והיא הכל וכל הארצות מתפרנסות ממנה באמת
@99 **בכל לבבכם ובכל נפשכם** . והלא כבר הזכיר בכל לבבך ובכל נפשך אלא אזהרה ליחיד ואזהרה לצבור לשון רש"י מספרי (עקב יג) ובאור הענין כי השם לא יעשה הנסים תמיד לתת מטר הארץ בכל עת יורה ומלקוש ולהוסיף בדגן ובתירוש וביצהר ולהרבות גם העשב בשדה לבהמה או שיעצור השמים וייבשו רק על מעשה רוב העם אבל היחיד הוא בזכותו יחיה והוא בעונו ימות והנה אמר כי בעשותם כל המצות מאהבה שלימה יעשה עמהם את כל הנסים האלה לטובה ואמר כי בעבדם ע"ז יעשה עמהם אות לרעה ודע כי הנסים לא יעשו לטובה או לרעה רק לצדיקים גמורים או לרשעים גמורים אבל הבינונים כדרך מנהגו של עולם יעשה בהם טובה או רעה כדרכם וכעלילותם
@101 **ואכלת ושבעת** . הרי זו ברכה אחרת שתהא ברכה מצויה בפת שבתוך מעיך ואכלת ושבעת לשון רש"י ור"א אמר "ואכלת ושבעת" שב אל דגנך תירושך ויצהרך לא אל הקרוב שהוא "עשב בשדך" והנכון בעיני שהוא שב אל הכל ואכלת ושבעת דגן ותירוש ויצהר וגם בני צאן ובקר ובספרי (עקב טו) ואכלת ושבעת כשבהמתך אוכלת ושובעת עובדת האדמה וכן הוא אומר (משלי יד ד) ורב תבואות בכח שור ד"א מן הולדות אע"פ שאין ראיה לדבר זכר לדבר שנאמר (ירמיהו לא יא) ובאו ורננו במרום ציון ונהרו אל טוב ה' על דגן ועל תירוש ועל יצהר ועל בני צאן ובקר וגו' וזהו הנכון
@104 **ושמתם את דברי אלה** . אף לאחר שתגלו היו מצוינין במצות הניחו תפילין עשו מזוזה כדי שלא יהו עליכם חדשים כשתחזרו וכן הוא אומר (שם שם כ) הציבי לך ציונים לשון רש"י וכבר כתבתי פירוש הענין כי המצות האלה חובת הגוף הם ודינם בכל מקום כמו בארץ אבל יש בו במדרש הזה סוד עמוק וכבר רמזתי ממנו (ויקרא יח כה) והנה החזיר במצות האלה תפילין ודברי תורה ומזוזה כאן פעם שנית לרמוז בהיקש הזה שנהיה חייבים בהם לאחר הגלות בחוצה לארץ ומהם נלמוד לכל המצות שהן חובת הגוף שחיובן בכל מקום ושנהיה פטורין בחוצה לארץ מחובת הקרקע כגון תרומה ומעשרות כך הוא נדרש בספרי (עקב יז) וכוונת המדרש מפני שסמך ושמתם אל ואבדתם אבל עיקר הכתוב בארץ דכתיב (פסוק כא) למען ירבו ימיכם וימי בניכם על האדמה או יאמר "למען ירבו ימיכם" שתשובו ותאריכו בה ימים לעולם ויתכן בדרך הפשט שבא להוסיף בכאן לדבר בם כי שם (לעיל ו ז) צוה ודברת אתה בם בשבתך בביתך וכאן אמר שנלמד אותם את בנינו עד שידברו בם הבנים בכל שעה וכן הוסיף בכאן ולמדתם אותם כי "ושננתם" שיספר להם המצות וכאן עד שילמדו אותם וידעום ויבינו אותם וטעמיהם לדבר עמך בם בכל העתים וכן הוסיף כאן כימי השמים על הארץ שהוא לדור דורים או הם השמים והארץ הראשונים וימי עולם והמשכיל יבין
@108 **ולדבקה בו** . אמר ר"א בסוף והוא סוד גדול ואין הסוד מטעם המקום הזה אולי יאמר לאהבה את ה' ללכת בכל דרכיו עד שתהיו ראויים לדבקה בו בסוף ונאמר ביהושע (כג ז ח) ובשם אלהיהם לא תזכירו ולא תשביעו ולא תעבדום ולא תשתחוו להם כי אם בה' אלהיכם תדבקו כאשר עשיתם עד היום הזה אם כן היא אזהרה מאזהרות ע"ז שלא תפרד מחשבתו מן השם אל אלהים אחרים שלא יחשוב שיהיה בע"ז שום עיקר אלא הכל אפס ואין והנה זה כמו שאמר עוד (להלן יג ה) ואותו תעבודו ובו תדבקון והכוונה להזהיר שלא יעבוד השם וזולתו אלא לה' לבדו יעבוד בלבו ובמעשיו ויתכן שתכלול הדביקה לומר שתהיה זוכר השם ואהבתו תמיד לא תפרד מחשבתך ממנו בלכתך בדרך ובשכבך ובקומך עד שיהיו דבריו עם בני אדם בפיו ובלשונו ולבו איננו עמהם אבל הוא לפני ה' ויתכן באנשי המעלה הזאת שתהיה נפשם גם בחייהם צרורה בצרור החיים כי הם בעצמם מעון לשכינה כאשר רמז בעל ספר הכוזרי וכבר הזכרתי מזה בפרשת העריות (ויקרא יח ד) ומה שאמר יהושע "כאשר עשיתם עד היום" כי בהיותם במדבר וענן ה' עליהם והמן יורד מן השמים והשלו עולה והבאר לפניהם תמיד וכל מעשיהם בידי שמים בדברים נסיים הנה מחשבתם ומעשיהם עם השם תמיד ולכן יזהירם יהושע שגם עתה בארץ בהסתלק מהם המעשים הנפלאים ההם תהיה מחשבתם בהם תמיד לדבקה בשם הנכבד והנורא ולא תפרד כוונתם מן השם
@110 **כל המקום אשר תדרך כף רגלכם בו לכם יהיה מן המדבר וגו'** . על דעת רבותינו הנה הם שתי הבטחות שכל מקום אשר ירצו לכבוש בארץ שנער וארץ אשור וזולתם יהיה שלהם והמצות כולן נוהגות בהם כי הכל ארץ ישראל ומן המדבר והלבנון ועד הים האחרון יהיה גבולכם שאתם חייבים לכבשו ולאבד משם העמים כמו שאמר כאן (פסוק כג) וירשתם גוים גדולים ועצומים מכם ולעקור ע"ז ומשמשיה כמו שהזכיר למעלה (ז ה כה) והבטיח כי לא יתיצב איש בפניכם בין בארץ הנזכרת בין בכל מקום אשר תדרוך כף רגלכם בו ומכאן יצא לרבותינו (חלה פ"ד מ"ז) המחלוקת בסוריא שקורין אותה כיבוש יחיד והטעם כי דוד כבש אותה ברצון נפשו שלא שאל באורים ותומים ולא נמלך בסנהדרין כי היה חייב להוריש כל שבעת הגוים בתחלה ואחרי כן אם ירצה ילך אל ארץ אחרת כאשר הבטיח השם בכאן ומפני שלא נעשה הכבוש ההוא כמצות התורה אמרו מקצתם לא שמיה כבוש ודינו במצות כדין חוצה לארץ וכך היא שנויה בספרי (עקב כד) ומקצתם יאמרו בתלמוד (ע"ז כא) דשמיה כבוש כי אף על פי שלא נעשה כסדר כיון שהלך שם וכבשה נתקיים בו לכם יהיה וארץ ישראל היא
